vorgeschlagenen Ausgleich als mögliche Lösung.","wrong":"Achte auf die Frage und die Informationen aus der Szene. Welche Antwort erfüllt das Ziel?"}}}'::jsonb,'der Lieferverkehr','einen Lieferverkehr')
 ) authored(template_key,level,category,word_de,article,content,answer_key,nominative,accusative)
 LOOP
  INSERT INTO daily_quest_private.slot_forms(category,word_de,article,nominative,accusative)
   VALUES(item.category,item.word_de,item.article,item.nominative,item.accusative) ON CONFLICT DO NOTHING;
  template:=NULL;
  INSERT INTO public.daily_quests(template_key,level,version,category,fallback_word_de,fallback_article,content)
   VALUES(item.template_key,item.level::public.cefr_code,1,item.category,item.word_de,item.article,item.content)
   ON CONFLICT(template_key) DO NOTHING RETURNING id INTO template;
  IF template IS NULL THEN SELECT q.id INTO template FROM public.daily_quests q WHERE q.template_key=item.template_key; END IF;
  -- Never overwrite an existing editorial version or silently change its keys.
  INSERT INTO daily_quest_private.template_keys(template_id,answer_key)
   SELECT q.id,item.answer_key FROM public.daily_quests q
   WHERE q.id=template AND q.version=1 AND q.content=item.content AND q.category=item.category
   ON CONFLICT DO NOTHING;
 END LOOP;
END $sitov_catalog$;
-- Repeat-free assignment selection retains the existing locks, level and vocabulary logic.
CREATE INDEX IF NOT EXISTS sitov_daily_quest_assignment_history_idx
 ON public.daily_quest_assignments(auth_user_id,template_id,quest_date DESC);
CREATE OR REPLACE FUNCTION daily_quest_private.ensure_assignment(p_user uuid) RETURNS uuid
LANGUAGE plpgsql VOLATILE SET search_path TO '' AS $$
DECLARE assigned uuid; template public.daily_quests%ROWTYPE; lexeme daily_quest_private.slot_forms%ROWTYPE;
 card uuid; source text:='fallback'; payload jsonb; keys jsonb; target public.cefr_code;
BEGIN
 SELECT a.id INTO assigned FROM public.daily_quest_assignments a WHERE a.auth_user_id=p_user AND a.quest_date=daily_quest_private.today();
 IF assigned IS NOT NULL THEN RETURN assigned; END IF;
 target:=daily_quest_private.target_level(p_user);
 -- Never-seen templates first; then the least recently assigned template.
 -- History belongs to this learner and level. Skips still count as seen.
 -- The starter is day zero; the catalogue interleaves twenty settings per round.
 -- Keep today's snapshot even if mastery or the active course changes today.
 SELECT q.* INTO template FROM public.daily_quests q
 JOIN daily_quest_private.template_keys k ON k.template_id=q.id
 LEFT JOIN LATERAL(SELECT max(a.quest_date) AS last_seen FROM public.daily_quest_assignments a
  WHERE a.auth_user_id=p_user AND a.template_id=q.id) history ON true
 WHERE q.is_active AND q.level=target
 ORDER BY history.last_seen ASC NULLS FIRST,
  coalesce((q.content->>'sitovCatalogDay')::integer,0),q.template_key,q.id LIMIT 1;
 IF template.id IS NULL THEN RETURN NULL; END IF;
 SELECT sf.*,c.id,CASE WHEN bool_or(p.box_number=1) THEN 'box1' ELSE 'recent_wrong' END
 INTO lexeme.category,lexeme.word_de,lexeme.article,lexeme.nominative,lexeme.accusative,card,source
 FROM public.learning_vocabulary_cards c JOIN public.learning_units u ON u.id=c.unit_id AND u.is_active
 JOIN daily_quest_private.slot_forms sf ON sf.category=template.category AND sf.word_de=c.word_de AND sf.article=c.article::text
 JOIN public.vocabulary_direction_progress p ON p.card_id=c.id AND p.auth_user_id=p_user
 LEFT JOIN public.vocabulary_focus_words f ON f.card_id=c.id AND f.auth_user_id=p_user
 WHERE learning_private.unit_allowed(u.id) AND (f.last_error_at>=now()-interval '30 days'
  OR (p.lapses>0 AND p.last_answered_at>=now()-interval '30 days')
  OR EXISTS(SELECT 1 FROM vocabulary_private.answer_receipts r WHERE r.auth_user_id=p_user AND r.progress_id=p.id
   AND r.is_correct=false AND r.created_at>=now()-interval '30 days'))
 GROUP BY sf.category,sf.word_de,sf.article,sf.nominative,sf.accusative,c.id
 ORDER BY bool_or(p.box_number=1) DESC,max(greatest(p.last_answered_at,f.last_error_at)) DESC NULLS LAST,c.id LIMIT 1;
 IF card IS NULL THEN SELECT sf.* INTO lexeme FROM daily_quest_private.slot_forms sf WHERE sf.category=template.category AND sf.word_de=template.fallback_word_de AND sf.article=template.fallback_article; source:='fallback'; END IF;
 IF lexeme.word_de IS NULL THEN RETURN NULL; END IF;
 payload:=daily_quest_private.render(template.content,lexeme.nominative,lexeme.accusative)
  || jsonb_build_object('level',template.level,'templateKey',template.template_key,'personalization',jsonb_build_object('source',source,'cardId',card));
 SELECT k.answer_key INTO keys FROM daily_quest_private.template_keys k WHERE k.template_id=template.id;
 INSERT INTO public.daily_quest_assignments(auth_user_id,quest_date,template_id,snapshot)
 VALUES(p_user,daily_quest_private.today(),template.id,payload) RETURNING id INTO assigned;
 INSERT INTO daily_quest_private.assignment_keys(assignment_id,answer_key) VALUES(assigned,keys);
 RETURN assigned;
END $$;

-- Staff browse the whole catalogue without creating assignments or login claims.
CREATE OR REPLACE FUNCTION daily_quest_private.sitov_catalog(p_level text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE actor uuid:=(SELECT auth.uid()); staff_role text; templates jsonb;
BEGIN
 IF actor IS NULL THEN RETURN daily_quest_private.error('not_authenticated'); END IF;
 SELECT p.role::text INTO staff_role FROM public.profiles p WHERE p.id=actor;
 IF staff_role IS NULL OR staff_role NOT IN('teacher','admin') THEN RETURN daily_quest_private.error('not_authorized'); END IF;
 IF p_level IS NULL OR p_level NOT IN('A1','A2','B1','B2','C1','C2') THEN RETURN daily_quest_private.error('invalid_input'); END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('templateKey',q.template_key,'level',q.level,
  'title',q.content->>'title','subtitle',q.content->>'subtitle','day',coalesce((q.content->>'sitovCatalogDay')::integer,0))
  ORDER BY coalesce((q.content->>'sitovCatalogDay')::integer,0),q.template_key),'[]'::jsonb)
 INTO templates FROM public.daily_quests q JOIN daily_quest_private.template_keys k ON k.template_id=q.id
 WHERE q.is_active AND q.level::text=p_level;
 RETURN jsonb_build_object('success',true,'templates',templates);
END $$;

CREATE OR REPLACE FUNCTION daily_quest_private.sitov_preview(p_level text,p_template_key text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$
DECLARE actor uuid:=(SELECT auth.uid()); staff_role text; template public.daily_quests%ROWTYPE;
 lexeme daily_quest_private.slot_forms%ROWTYPE; payload jsonb; keys jsonb;
BEGIN
 IF actor IS NULL THEN RETURN daily_quest_private.error('not_authenticated'); END IF;
 SELECT p.role::text INTO staff_role FROM public.profiles p WHERE p.id=actor;
 IF staff_role IS NULL OR staff_role NOT IN('teacher','admin') THEN RETURN daily_quest_private.error('not_authorized'); END IF;
 IF p_level IS NULL OR p_level NOT IN('A1','A2','B1','B2','C1','C2') OR p_template_key IS NULL
  OR length(p_template_key)>120 OR p_template_key !~ '^sitov-[a-z0-9-]+$' THEN RETURN daily_quest_private.error('invalid_input'); END IF;
 SELECT q.* INTO template FROM public.daily_quests q JOIN daily_quest_private.template_keys k ON k.template_id=q.id
 WHERE q.is_active AND q.level::text=p_level AND q.template_key=p_template_key;
 IF template.id IS NULL THEN RETURN daily_quest_private.error('no_template'); END IF;
 SELECT k.answer_key INTO keys FROM daily_quest_private.template_keys k WHERE k.template_id=template.id;
 SELECT sf.* INTO lexeme FROM daily_quest_private.slot_forms sf WHERE sf.category=template.category
  AND sf.word_de=template.fallback_word_de AND sf.article=template.fallback_article;
 IF lexeme.word_de IS NULL THEN RETURN daily_quest_private.error('no_template'); END IF;
 payload:=daily_quest_private.render(template.content,lexeme.nominative,lexeme.accusative) || jsonb_build_object(
  'id',template.id,'date',daily_quest_private.today(),'level',template.level,'templateKey',template.template_key,
  'status','active','completedStepIds','[]'::jsonb,'personalization',jsonb_build_object('source','fallback','cardId',NULL));
 RETURN jsonb_build_object('success',true,'quest',payload,'answerKey',jsonb_build_object('steps',keys->'steps'));
END $$;

CREATE OR REPLACE FUNCTION public.get_sitov_daily_quest_catalog(p_level text DEFAULT 'A1')
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path TO '' AS $$ SELECT daily_quest_private.sitov_catalog(p_level) $$;
CREATE OR REPLACE FUNCTION public.get_sitov_daily_quest_preview(p_level text,p_template_key text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path TO '' AS $$ SELECT daily_quest_private.sitov_preview(p_level,p_template_key) $$;
REVOKE ALL ON FUNCTION daily_quest_private.sitov_catalog(text),daily_quest_private.sitov_preview(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION daily_quest_private.sitov_catalog(text),daily_quest_private.sitov_preview(text,text) TO authenticated;
REVOKE ALL ON FUNCTION public.get_sitov_daily_quest_catalog(text),public.get_sitov_daily_quest_preview(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_sitov_daily_quest_catalog(text),public.get_sitov_daily_quest_preview(text,text) TO authenticated;

COMMENT ON TABLE public.daily_quests IS 'Sitov Academy daily journeys: six starters plus 100 authored scenes per A1, A2, B1 and B2. Private solutions are isolated.';
NOTIFY pgrst,'reload schema';

-- END SITOV DAILY QUEST CATALOG

-- Consolidated correction: 20261003184422_sitov_confirmed_registration_monthly_access.sql
-- Keep the existing atomic booking/invoice workflow and every data row intact.
-- A monthly draft or trial is not evidence that the original registration was
-- accepted. A school-set confirmed_at retains that evidence when the initial
-- next-month registration is edited or paused. Rejected registrations do not
-- grant access. The evidence must belong to the verified person.
DO $sitov$
DECLARE definition text;
BEGIN
  definition := pg_get_functiondef('business_private.save_month(date,jsonb,boolean,uuid,integer)'::regprocedure);
  IF position('sitov_confirmed_registration_required' IN definition) = 0 THEN
    IF position('select * into strict p from public.people where auth_user_id=auth.uid() for update;' IN definition) = 0 THEN
      RAISE EXCEPTION 'Unexpected save_month definition; apply no partial access change';
    END IF;
    definition := replace(definition,
      'select * into strict p from public.people where auth_user_id=auth.uid() for update;',
      'select * into strict p from public.people where auth_user_id=auth.uid() for update;
 if coalesce((business_private.claim_person()->>''unresolved'')::boolean,false)
  or not exists(select 1 from public.bookings where person_id=p.id and kind=''registration'' and status<>''rejected'' and (status=''confirmed'' or confirmed_at is not null)) then
  raise exception using errcode=''42501'',message=''sitov_confirmed_registration_required'';
 end if;');
    EXECUTE definition;
  END IF;
END $sitov$;

-- BEGIN SITOV PREPARED GERMAN AUDIO

-- Consolidated audio migration: 20261003191609_sitov_audio_preparation_requests.sql
-- German inference runs only in the offline authoring workflow. No learner,
-- profile or progress identifiers are stored with these deduplicated texts.
CREATE TABLE IF NOT EXISTS public.sitov_audio_preparation_requests (
  cache_path text PRIMARY KEY,
  text text NOT NULL CHECK (char_length(text) BETWEEN 1 AND 3000 AND text = btrim(text)),
  profile_fingerprint text NOT NULL CHECK (profile_fingerprint ~ '^[0-9a-f]{64}$'),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'prepared')),
  created_at timestamptz NOT NULL DEFAULT now(),
  prepared_at timestamptz,
  CONSTRAINT sitov_audio_preparation_path CHECK (cache_path ~ '^sitov-qwen-v[0-9]+/de/[0-9a-f]{64}\.mp3$'),
  CONSTRAINT sitov_audio_preparation_state CHECK (
    (status = 'pending' AND prepared_at IS NULL) OR
    (status = 'prepared' AND prepared_at IS NOT NULL)
  )
);

CREATE INDEX IF NOT EXISTS sitov_audio_preparation_pending
  ON public.sitov_audio_preparation_requests (created_at, cache_path)
  WHERE status = 'pending';

ALTER TABLE public.sitov_audio_preparation_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sitov_audio_preparation_requests FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.sitov_audio_preparation_requests TO service_role;
COMMENT ON TABLE public.sitov_audio_preparation_requests IS
  'Sitov Academy internal offline German audio preparation queue; service role only.';


-- Consolidated audio migration: 20261003192958_sitov_prepared_own_vocabulary.sql
-- Apply only after the complete Qwen corpus has been imported and audited.
-- Keep both original function signatures/OIDs: existing wrappers and callers
-- retain their dependencies. No learner state or authored IDs are rewritten.

-- Prepared metadata is a service-owned proof. Restrictive write guards also
-- hold if another module later introduces a broader permissive Storage policy.
DROP POLICY IF EXISTS sitov_qwen_cache_service_insert ON storage.objects;
CREATE POLICY sitov_qwen_cache_service_insert ON storage.objects AS RESTRICTIVE
 FOR INSERT TO anon, authenticated WITH CHECK (bucket_id <> 'audio_cache');
DROP POLICY IF EXISTS sitov_qwen_cache_service_update ON storage.objects;
CREATE POLICY sitov_qwen_cache_service_update ON storage.objects AS RESTRICTIVE
 FOR UPDATE TO anon, authenticated USING (bucket_id <> 'audio_cache') WITH CHECK (bucket_id <> 'audio_cache');
DROP POLICY IF EXISTS sitov_qwen_cache_service_delete ON storage.objects;
CREATE POLICY sitov_qwen_cache_service_delete ON storage.objects AS RESTRICTIVE
 FOR DELETE TO anon, authenticated USING (bucket_id <> 'audio_cache');

CREATE OR REPLACE FUNCTION vocabulary_private.sitov_normalize_audio_text(p_text text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path TO '' AS $$
 SELECT btrim(regexp_replace(pg_catalog.normalize(coalesce(p_text,''),'NFC'),
   U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+', ' ', 'g'));
$$;
REVOKE ALL ON FUNCTION vocabulary_private.sitov_normalize_audio_text(text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION vocabulary_private.sitov_prepared_german_audio_url(p_text text)
RETURNS text LANGUAGE plpgsql SET search_path TO '' AS $$
DECLARE
 spoken text := vocabulary_private.sitov_normalize_audio_text(p_text);
 fingerprint constant text := '96db5949cf9ba060eb5fbeeec3b472d232d55e0b22dc2512cf65dc53c8c47df5';
 preimage text;
 cache_path text;
 authored jsonb;
 object_metadata jsonb;
 timings jsonb;
 timing jsonb;
 previous_end numeric := 0;
 start_seconds numeric;
 end_seconds numeric;
BEGIN
 -- Exact JSON.stringify key order and whitespace of neuralAudioPath().
 preimage := '{"text":' || to_json(spoken)::text ||
   ',"voice":"sitov-qwen-male-de-v1","rate":"qwen-native-1-lufs-18-aligned-v1","format":"audio-24khz-48kbitrate-mono-mp3","leadIn":0.35,"profile":"' || fingerprint || '"}';
 cache_path := 'sitov-qwen-v1/de/' || encode(sha256(convert_to(preimage,'UTF8')),'hex') || '.mp3';
 SELECT o.user_metadata, o.metadata INTO authored, object_metadata
 FROM storage.objects o WHERE o.bucket_id='audio_cache' AND o.name=cache_path
   AND o.archived_at IS NULL AND coalesce(o.is_delete_marker,false)=false
 FOR SHARE;
 IF NOT FOUND OR authored->>'engine' IS DISTINCT FROM 'qwen3-tts'
   OR authored->>'voice' IS DISTINCT FROM 'sitov-qwen-male-de-v1'
   OR authored->>'revision' IS DISTINCT FROM 'sitov-qwen-base-bf16-v1'
   OR authored->>'profileFingerprint' IS DISTINCT FROM fingerprint
   OR authored->>'textSha256' IS DISTINCT FROM encode(sha256(convert_to(spoken,'UTF8')),'hex')
   OR coalesce(authored->>'audioSha256','') !~ '^[0-9a-f]{64}$'
   OR object_metadata->>'mimetype' IS DISTINCT FROM 'audio/mpeg'
   OR jsonb_typeof(object_metadata->'size') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
 END IF;
 IF (object_metadata->>'size')::numeric NOT BETWEEN 1 AND 2097152 THEN
   RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
 END IF;
 timings := authored->'wordTimings';
 IF jsonb_typeof(timings) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
 END IF;
 IF spoken='' OR jsonb_array_length(timings) NOT BETWEEN 1 AND 1500
   OR jsonb_array_length(timings) <> cardinality(string_to_array(spoken,' ')) THEN
   RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
 END IF;
 FOR timing IN SELECT value FROM jsonb_array_elements(timings) LOOP
   IF jsonb_typeof(timing->'start') IS DISTINCT FROM 'number'
     OR jsonb_typeof(timing->'end') IS DISTINCT FROM 'number' THEN
     RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
   END IF;
   start_seconds := (timing->>'start')::numeric;
   end_seconds := (timing->>'end')::numeric;
   IF start_seconds < previous_end OR end_seconds < start_seconds OR end_seconds > 1200 THEN
     RAISE EXCEPTION 'prepared_audio_required' USING ERRCODE='22023';
   END IF;
   previous_end := end_seconds;
 END LOOP;
 RETURN '/supabase/storage/v1/object/public/audio_cache/' || cache_path;
END $$;
REVOKE ALL ON FUNCTION vocabulary_private.sitov_prepared_german_audio_url(text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION vocabulary_private.add_own_word(p_level text, p_word_de text, p_article text, p_translation text, p_locale text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE actor uuid:=auth.uid(); own_unit uuid; new_card uuid; activated boolean; prepared_audio_url text;
 word text:=vocabulary_private.sitov_normalize_audio_text(p_word_de);
 translated text:=btrim(regexp_replace(coalesce(p_translation,''),'\s+',' ','g'));
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
 IF NOT trainer_access_private.allowed(p_level,'vocabulary') THEN RAISE EXCEPTION 'trainer_access_denied' USING ERRCODE='42501'; END IF;
 -- Die Übersetzung steht in der Sprache der Oberfläche: Daraus fragt der
 -- Trainer die Richtung Deutsch → eigene Sprache ab (answer_key).
 IF p_locale IS NULL OR p_locale NOT IN('en','ru','uk','tr') THEN RAISE EXCEPTION 'invalid_language' USING ERRCODE='22023'; END IF;
 IF length(word) NOT BETWEEN 1 AND 120 OR length(translated) NOT BETWEEN 1 AND 200
  OR (p_article IS NOT NULL AND p_article NOT IN('der','die','das')) THEN
  RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF;
 -- The prepared Storage object is required before any unit/card insert.
 prepared_audio_url:=vocabulary_private.sitov_prepared_german_audio_url(concat(coalesce(p_article,''),' ',word));
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||actor::text,0));
 SELECT id INTO own_unit FROM public.learning_units WHERE owner_auth_user_id=actor AND level=p_level AND trainer='vocabulary';
 IF own_unit IS NULL THEN
  INSERT INTO public.learning_units(level,trainer,label,sort_order,is_active,owner_auth_user_id)
   VALUES(p_level,'vocabulary','Eigene Wörter',1000000,true,actor) RETURNING id INTO own_unit;
 END IF;
 -- 1000 = eine initialize_vocabulary_cards-Anfrage aktiviert die ganze Lektion.
 IF (SELECT count(*) FROM public.learning_vocabulary_cards c WHERE c.unit_id=own_unit)>=1000 THEN
  RAISE EXCEPTION 'own_word_limit' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.learning_vocabulary_cards c WHERE c.unit_id=own_unit
  AND lower(c.word_de)=lower(word) AND coalesce(c.article::text,'')=coalesce(p_article,'')) THEN
  RAISE EXCEPTION 'own_word_exists' USING ERRCODE='23505'; END IF;
 activated:=EXISTS(SELECT 1 FROM public.vocabulary_direction_progress v JOIN public.learning_vocabulary_cards c ON c.id=v.card_id
  WHERE v.auth_user_id=actor AND c.unit_id=own_unit);
 INSERT INTO public.learning_vocabulary_cards(unit_id,word_de,article,sentence_practice,audio_url)
  VALUES(own_unit,word,p_article::public.grammatical_article,false,prepared_audio_url) RETURNING id INTO new_card;
 INSERT INTO public.vocabulary_translations(card_id,locale,translation) VALUES(new_card,p_locale,translated);
 IF activated THEN
  INSERT INTO public.vocabulary_direction_progress(auth_user_id,card_id,direction,box_number,next_review_date)
   SELECT actor,new_card,d::public.vocabulary_direction,1,now() FROM unnest(ARRAY['de_to_native','native_to_de']) d;
 END IF;
 RETURN jsonb_build_object('cardId',new_card,'activated',activated);
END $$;
REVOKE ALL ON FUNCTION vocabulary_private.add_own_word(text,text,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION vocabulary_private.add_own_word(text,text,text,text,text) TO authenticated;


CREATE OR REPLACE FUNCTION public.add_own_vocabulary(p_level text, p_word_de text, p_article text, p_translation text, p_locale text)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO '' AS $$
DECLARE boundary_state text; boundary_message text; boundary_code text;
BEGIN
 RETURN vocabulary_private.add_own_word(p_level,p_word_de,p_article,p_translation,p_locale);
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS boundary_state=RETURNED_SQLSTATE,boundary_message=MESSAGE_TEXT;
  boundary_code:=CASE WHEN boundary_message=ANY(ARRAY[
   'authentication_required','trainer_access_denied','invalid_language','own_word_exists','own_word_limit','prepared_audio_required',
   'not_authorized','not_authenticated','invalid_input','request_failed','conflict','not_found'
  ]) THEN boundary_message
  WHEN boundary_state='42501' THEN 'not_authorized'
  WHEN boundary_state IN('23502','23503','23514','22P02','22023','22007') THEN 'invalid_input'
  WHEN boundary_state IN('23505','PT409','40001') THEN 'conflict'
  WHEN boundary_state='40P01' THEN 'retry_required'
  WHEN boundary_state IN('P0002','02000') THEN 'not_found'
  ELSE 'request_failed' END;
  RETURN jsonb_build_object('error',boundary_code,'message',CASE
   WHEN boundary_code='prepared_audio_required' THEN 'Prepare and upload the German audio before adding this word.'
   WHEN boundary_code='own_word_exists' THEN 'This word is already in your own words.'
   WHEN boundary_code='own_word_limit' THEN 'Your own words list is full.'
   WHEN boundary_state='42501' THEN 'The request is not authorized.'
   WHEN boundary_code IN('conflict','retry_required') THEN 'Reload and retry the request.'
   WHEN boundary_code='invalid_input' THEN 'The request contains invalid data.'
   ELSE 'The request could not be completed.' END,'sqlstate',boundary_state);
END $$;
REVOKE ALL ON FUNCTION public.add_own_vocabulary(text,text,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.add_own_vocabulary(text,text,text,text,text) TO authenticated, service_role;


-- Consolidated audio migration: 20261003195521_sitov_prepared_learning_publication.sql
-- Apply after 20261003192958 and after the Qwen corpus import/audit.
-- The CMS server action is not the only caller: authenticated staff can invoke
-- this RPC directly. Keep its OID, invoker mode, ACLs, IDs and error contract.

CREATE OR REPLACE FUNCTION learning_private.sitov_learning_audio_texts(
 p_trainer text, p_fields jsonb, p_translations jsonb
) RETURNS text[] LANGUAGE plpgsql IMMUTABLE SET search_path TO '' AS $$
DECLARE
 texts text[] := ARRAY[]::text[];
 answer text := CASE WHEN jsonb_typeof(p_fields->'content'->'correct_answer')='string'
   THEN p_fields->'content'->>'correct_answer' ELSE '' END;
 question text := CASE WHEN jsonb_typeof(p_fields->'content'->'question')='string'
   THEN p_fields->'content'->>'question' ELSE '' END;
 before_text text := CASE WHEN jsonb_typeof(p_fields->'content'->'text_before')='string'
   THEN p_fields->'content'->>'text_before' ELSE '' END;
 after_text text := CASE WHEN jsonb_typeof(p_fields->'content'->'text_after')='string'
   THEN p_fields->'content'->>'text_after' ELSE '' END;
BEGIN
 -- Mirror preparedLearningAudioTexts() after learningWritePayload() has moved
 -- the editor's German context sentence into its exact-locale translation.
 IF p_trainer='vocabulary' THEN
  IF jsonb_typeof(p_fields->'word_de')='string' THEN
   texts := array_append(texts, concat(CASE WHEN jsonb_typeof(p_fields->'article')='string'
     AND p_fields->>'article'<>'none' THEN p_fields->>'article' ELSE '' END,' ',p_fields->>'word_de'));
  END IF;
  IF jsonb_typeof(p_translations)='array' THEN
   SELECT texts || coalesce(array_agg(t->>'context_sentence'),'{}'::text[]) INTO texts
   FROM jsonb_array_elements(p_translations) t
   WHERE t->>'locale'='de' AND jsonb_typeof(t->'context_sentence')='string';
  END IF;
 ELSIF p_trainer='pronunciation' THEN
  IF jsonb_typeof(p_fields->'sentence_de')='string' THEN
   texts := array_append(texts,p_fields->>'sentence_de');
  END IF;
 ELSIF p_trainer='exercises' THEN
  IF p_fields->>'type'='fill_in_blank' THEN
   texts := ARRAY[answer,before_text || answer || after_text];
  ELSIF p_fields->>'type'='multiple_choice' THEN
   -- JS String.replace replaces the first literal marker, not all markers.
   texts := ARRAY[CASE WHEN strpos(question,'___')>0 THEN
     substr(question,1,strpos(question,'___')-1) || answer || substr(question,strpos(question,'___')+3)
     ELSE question || ' ' || answer END];
  ELSIF p_fields->>'type'='sentence_building' THEN
   texts := ARRAY[answer];
  END IF;
 END IF;
 RETURN ARRAY(SELECT DISTINCT vocabulary_private.sitov_normalize_audio_text(t)
  FROM unnest(texts) t WHERE vocabulary_private.sitov_normalize_audio_text(t)<>'');
END $$;
REVOKE ALL ON FUNCTION learning_private.sitov_learning_audio_texts(text,jsonb,jsonb)
 FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION learning_private.sitov_require_prepared_learning_audio(
 p_trainer text, p_fields jsonb, p_translations jsonb, p_unit uuid
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE
 invoking_role text := coalesce(nullif(current_setting('role',true),'none'),session_user);
 active boolean;
 item uuid;
 stored_fields jsonb;
 stored_translations jsonb := '[]'::jsonb;
 spoken text;
 existing_audio text;
 prepared_audio text;
BEGIN
 -- Definer rights are only a bridge to the closed, service-owned Storage
 -- metadata proof. Check the actual caller before any Storage lookup; never
 -- trust an editable JWT role claim or return metadata to non-staff callers.
 IF invoking_role NOT IN('service_role','postgres','supabase_admin')
  AND (auth.uid() IS NULL OR coalesce(identity_private.current_profile_role(),'') NOT IN('teacher','admin')) THEN
  RAISE EXCEPTION 'Staff required' USING ERRCODE='42501';
 END IF;
 SELECT u.is_active INTO active FROM public.learning_units u WHERE u.id=p_unit FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Content unavailable' USING ERRCODE='23514'; END IF;
 IF NOT active OR p_trainer='videos' THEN RETURN; END IF;

 -- The CMS supplies only its saved ID; path imports supply the actual row.
 -- Read the authoritative, locked row and translations after their write.
 -- Caller-provided text, translations and URLs never constitute the proof.
 item := (p_fields->>'id')::uuid;
 IF p_trainer='vocabulary' THEN
  SELECT to_jsonb(c) INTO stored_fields FROM public.learning_vocabulary_cards c
   WHERE c.id=item AND c.unit_id=p_unit FOR UPDATE;
 ELSIF p_trainer='pronunciation' THEN
  SELECT to_jsonb(r) INTO stored_fields FROM public.learning_reading_texts r
   WHERE r.id=item AND r.unit_id=p_unit FOR UPDATE;
 ELSIF p_trainer='exercises' THEN
  SELECT to_jsonb(e) INTO stored_fields FROM public.learning_exercises e
   WHERE e.id=item AND e.unit_id=p_unit FOR UPDATE;
 ELSE RAISE EXCEPTION 'Content unavailable' USING ERRCODE='23514';
 END IF;
 IF stored_fields IS NULL THEN RAISE EXCEPTION 'Content unavailable' USING ERRCODE='23514'; END IF;
 IF p_trainer='vocabulary' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('locale',t.locale,'context_sentence',t.context_sentence)),'[]'::jsonb)
   INTO stored_translations FROM public.vocabulary_translations t WHERE t.card_id=item AND t.locale='de';
 END IF;
 FOR spoken IN SELECT unnest(learning_private.sitov_learning_audio_texts(p_trainer,stored_fields,stored_translations)) LOOP
  PERFORM vocabulary_private.sitov_prepared_german_audio_url(spoken);
 END LOOP;

 -- Persist the reference within the same publication transaction. Fill's
 -- stored URL plays its answer word; its full sentence uses a separate button.
 -- Multiple choice has exactly one joined/replaced UI utterance.
 IF p_trainer='vocabulary' THEN
  spoken := concat(CASE WHEN stored_fields->>'article'<>'none' THEN stored_fields->>'article' ELSE '' END,' ',stored_fields->>'word_de');
 ELSIF p_trainer='pronunciation' THEN spoken := stored_fields->>'sentence_de';
 ELSIF stored_fields->>'type'='fill_in_blank' THEN spoken := stored_fields->'content'->>'correct_answer';
 ELSIF stored_fields->>'type'='multiple_choice' THEN
  spoken := (learning_private.sitov_learning_audio_texts(p_trainer,stored_fields,stored_translations))[1];
 ELSE RETURN;
 END IF;
 existing_audio := CASE WHEN p_trainer='exercises' THEN stored_fields->>'solution_audio_url' ELSE stored_fields->>'audio_url' END;
 IF nullif(btrim(existing_audio),'') IS NULL OR strpos(existing_audio,'/audio_cache/')>0 THEN
  prepared_audio := vocabulary_private.sitov_prepared_german_audio_url(spoken);
  IF p_trainer='vocabulary' THEN
   UPDATE public.learning_vocabulary_cards SET audio_url=prepared_audio WHERE id=item AND unit_id=p_unit AND audio_url IS DISTINCT FROM prepared_audio;
  ELSIF p_trainer='pronunciation' THEN
   UPDATE public.learning_reading_texts SET audio_url=prepared_audio WHERE id=item AND unit_id=p_unit AND audio_url IS DISTINCT FROM prepared_audio;
  ELSE
   UPDATE public.learning_exercises SET solution_audio_url=prepared_audio WHERE id=item AND unit_id=p_unit AND solution_audio_url IS DISTINCT FROM prepared_audio;
  END IF;
 END IF;
END $$;
REVOKE ALL ON FUNCTION learning_private.sitov_require_prepared_learning_audio(text,jsonb,jsonb,uuid)
 FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION learning_private.sitov_require_prepared_learning_audio(text,jsonb,jsonb,uuid)
 TO authenticated, service_role;

-- The production runner uses supabase_admin, also owner of the private audio
-- proof. Refuse an incompatible owner instead of opening it to app roles.
DO $owner$
DECLARE bridge_owner text;
BEGIN
 SELECT pg_get_userbyid(proowner) INTO bridge_owner FROM pg_proc
 WHERE oid='learning_private.sitov_require_prepared_learning_audio(text,jsonb,jsonb,uuid)'::regprocedure;
 IF NOT has_schema_privilege(bridge_owner,'vocabulary_private','USAGE')
  OR NOT has_function_privilege(bridge_owner,'vocabulary_private.sitov_normalize_audio_text(text)','EXECUTE')
  OR NOT has_function_privilege(bridge_owner,'vocabulary_private.sitov_prepared_german_audio_url(text)','EXECUTE') THEN
  RAISE EXCEPTION 'sitov_audio_bridge_owner_unavailable' USING ERRCODE='42501';
 END IF;
END $owner$;

DO $publication$
DECLARE definition text; before_text text; after_text text;
BEGIN
 definition := pg_get_functiondef('public.save_learning_content(text,jsonb,uuid)'::regprocedure);
 IF strpos(definition,'-- sitov-prepared-learning-publication-v1')>0 THEN RETURN; END IF;

 -- Existing shared vocabulary/exercise units keep their current state. Only a
 -- newly created unit uses the requested draft flag. A false flag on a payload
 -- cannot bypass the guard when the actual target unit remains active.
 before_text := $before$ELSE target_unit:=learning_private.ensure_unit(NULL,unit_data->>'level',p_trainer,unit_data->>'label'); END IF;$before$;
 after_text := $after$ELSE target_unit:=learning_private.ensure_unit(NULL,unit_data->>'level',p_trainer,unit_data->>'label',
    coalesce((unit_data->>'is_active')::boolean,old_meta.is_active,true),coalesce((unit_data->>'sort_order')::integer,old_meta.sort_order,100)); END IF;$after$;
 IF strpos(definition,before_text)=0 THEN
  RAISE EXCEPTION 'sitov_audio_publication_unit_source_drift' USING ERRCODE='23514';
 END IF;
 definition := replace(definition,before_text,after_text);

 before_text := $before$ RETURN jsonb_build_object('id',item);$before$;
 after_text := $after$ -- sitov-prepared-learning-publication-v1
 -- Preserve existing content-quality errors, then verify every spoken source
 -- before this mutation can commit. A miss rolls the enclosing block back,
 -- including newly inserted units/cards and any previous-unit cleanup.
 PERFORM learning_private.sitov_require_prepared_learning_audio(p_trainer,jsonb_build_object('id',item),'[]'::jsonb,target_unit);
 RETURN jsonb_build_object('id',item);$after$;
 IF strpos(definition,before_text)=0 THEN
  RAISE EXCEPTION 'sitov_audio_publication_guard_source_drift' USING ERRCODE='23514';
 END IF;
 definition := replace(definition,before_text,after_text);

 before_text := $before$ WHEN OTHERS THEN RETURN jsonb_build_object('error','save_failed','message','Content could not be saved.');$before$;
 after_text := $after$ WHEN OTHERS THEN RETURN jsonb_build_object(
  'error',CASE WHEN SQLERRM='prepared_audio_required' THEN 'prepared_audio_required' ELSE 'save_failed' END,
  'message',CASE WHEN SQLERRM='prepared_audio_required' THEN 'Prepare and upload the German audio before publishing this content.' ELSE 'Content could not be saved.' END);$after$;
 IF strpos(definition,before_text)=0 THEN
  RAISE EXCEPTION 'sitov_audio_publication_error_source_drift' USING ERRCODE='23514';
 END IF;
 EXECUTE replace(definition,before_text,after_text);
END $publication$;


-- Consolidated audio migration: 20261003201130_sitov_prepared_path_publication.sql
-- Apply after 20261003195521. Both staff and service seed imports use this
-- reviewed inner catalog writer. No curriculum, IDs or progress are rewritten.
DO $path_publication$
DECLARE definition text; before_text text; after_text text;
BEGIN
 definition := pg_get_functiondef('path_private.import_path_catalog(jsonb,uuid)'::regprocedure);
 IF strpos(definition,'-- sitov-prepared-path-publication-v1')=0 THEN
  before_text := $before$ RETURN jsonb_build_object('unit_id',unit,'node_count',node_count,'exercise_count',exercise_count);$before$;
  after_text := $after$ -- sitov-prepared-path-publication-v1
 -- Public wrappers authorize staff/the actual service role before this helper.
 -- Verify after existing shape/quality/pool validation and before commit; the
 -- wrapper exception block rolls back the entire import on an audio miss.
 -- ExerciseClient currently plays only fill-in-blank and multiple-choice.
 -- Include retained old rows too: its legacy query does not filter path flags.
 FOR exercise IN SELECT to_jsonb(e) FROM public.learning_exercises e
  WHERE e.unit_id=unit AND e.type IN('fill_in_blank','multiple_choice') LOOP
  PERFORM learning_private.sitov_require_prepared_learning_audio('exercises',exercise,'[]'::jsonb,unit);
 END LOOP;
 RETURN jsonb_build_object('unit_id',unit,'node_count',node_count,'exercise_count',exercise_count);$after$;
  IF strpos(definition,before_text)=0 THEN
   RAISE EXCEPTION 'sitov_audio_path_publication_source_drift' USING ERRCODE='23514';
  END IF;
  EXECUTE replace(definition,before_text,after_text);
 END IF;

 -- Keep the installed path error allow-list, shape and all existing domain
 -- codes. Add one explicit, safe operator response shared by both RPCs.
 definition := pg_get_functiondef('path_private.error(text,text)'::regprocedure);
 IF strpos(definition,'-- sitov-prepared-path-error-v1')=0 THEN
  before_text := $before$ SELECT jsonb_build_object('error',CASE WHEN p_message=ANY($before$;
  after_text := $after$ -- sitov-prepared-path-error-v1
 SELECT CASE WHEN p_message='prepared_audio_required' THEN jsonb_build_object(
  'error','prepared_audio_required','sqlstate',p_state,
  'message','Prepare the German audio locally and import the verified recordings before retrying the seed import.')
 ELSE jsonb_build_object('error',CASE WHEN p_message=ANY($after$;
  IF strpos(definition,before_text)=0 THEN
   RAISE EXCEPTION 'sitov_audio_path_error_source_drift' USING ERRCODE='23514';
  END IF;
  definition := replace(definition,before_text,after_text);
  before_text := $before$ END,'sqlstate',p_state);$before$;
  after_text := $after$ END,'sqlstate',p_state) END;$after$;
  IF strpos(definition,before_text)=0 THEN
   RAISE EXCEPTION 'sitov_audio_path_error_result_source_drift' USING ERRCODE='23514';
  END IF;
  EXECUTE replace(definition,before_text,after_text);
 END IF;
END $path_publication$;


-- END SITOV PREPARED GERMAN AUDIO


-- BEGIN SITOV VOCABULARY CHUNKS IMPORT
-- Sitov Academy word/chunk cards. Apply after prepared publication migration 71.
-- Additive only: legacy IDs, answers, progress, recordings and activity remain.
ALTER TABLE public.learning_vocabulary_cards
 ADD COLUMN IF NOT EXISTS content_kind text NOT NULL DEFAULT 'vocabulary',
 ADD COLUMN IF NOT EXISTS chunk_de text,
 ADD COLUMN IF NOT EXISTS source_id text;
ALTER TABLE public.vocabulary_translations ADD COLUMN IF NOT EXISTS chunk_translation text;
DO $constraints$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.learning_vocabulary_cards'::regclass AND conname='sitov_vocabulary_kind_check') THEN
  ALTER TABLE public.learning_vocabulary_cards ADD CONSTRAINT sitov_vocabulary_kind_check CHECK(content_kind IN('vocabulary','chunk'));
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.learning_vocabulary_cards'::regclass AND conname='sitov_vocabulary_chunk_check') THEN
  ALTER TABLE public.learning_vocabulary_cards ADD CONSTRAINT sitov_vocabulary_chunk_check CHECK(chunk_de IS NULL OR length(btrim(chunk_de)) BETWEEN 1 AND 500);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.learning_vocabulary_cards'::regclass AND conname='sitov_vocabulary_chunk_article_check') THEN
  ALTER TABLE public.learning_vocabulary_cards ADD CONSTRAINT sitov_vocabulary_chunk_article_check CHECK(content_kind<>'chunk' OR article IS NULL OR article='none');
 END IF;
END $constraints$;
CREATE UNIQUE INDEX IF NOT EXISTS sitov_vocabulary_source_idx ON public.learning_vocabulary_cards(source_id) WHERE source_id IS NOT NULL;
COMMENT ON COLUMN public.learning_vocabulary_cards.content_kind IS 'A teacher vocabulary_card remains one word card with an embedded chunk; only an explicit chunk_card is a separate card.';
COMMENT ON COLUMN public.learning_vocabulary_cards.chunk_de IS 'Same-card German usage chunk; separate prepared audio required before publication.';
COMMENT ON COLUMN public.learning_vocabulary_cards.source_id IS 'Stable Sitov Academy authoring identity; independent of existing database/card progress IDs.';
CREATE TABLE IF NOT EXISTS vocabulary_private.sitov_seed_card_origins(
 card_id uuid PRIMARY KEY REFERENCES public.learning_vocabulary_cards(id) ON DELETE CASCADE,
 preserve_core boolean NOT NULL
);
ALTER TABLE vocabulary_private.sitov_seed_card_origins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE vocabulary_private.sitov_seed_card_origins FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON TABLE vocabulary_private.sitov_seed_card_origins TO service_role;

-- Explicit, baseline-checked male-character revisions retain historical German
-- answers separately from the current display/audio text. No old variant is
-- added to the spoken sources or exposed as learner content.
CREATE TABLE IF NOT EXISTS vocabulary_private.sitov_legacy_card_revisions(
 card_id uuid PRIMARY KEY REFERENCES public.learning_vocabulary_cards(id) ON DELETE CASCADE,
 baseline jsonb NOT NULL, replacement jsonb NOT NULL,
 word_answers text[] NOT NULL, sentence_answers text[] NOT NULL
);
ALTER TABLE vocabulary_private.sitov_legacy_card_revisions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE vocabulary_private.sitov_legacy_card_revisions FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON TABLE vocabulary_private.sitov_legacy_card_revisions TO service_role;

-- Existing accepted sentence arrays keep their exact values. Historical word
-- answers need their own format, because sentence alternatives have never been
-- word answers. Keep function OIDs/security/ACLs and both RPC error boundaries.
DO $historic_answers$
DECLARE definition text; before_text text; after_text text; signature text;
BEGIN
 definition:=pg_get_functiondef('vocabulary_private.answer_key(uuid,text,text)'::regprocedure);
 IF strpos(definition,'-- sitov-legacy-vocabulary-answers-v1')=0 THEN
  before_text:=$before$ IF nullif(btrim(canonical),'') IS NULL THEN RAISE EXCEPTION 'exercise_unavailable' USING ERRCODE='23514'; END IF;$before$;
  after_text:=$after$ -- sitov-legacy-vocabulary-answers-v1
 IF p_direction='native_to_de' THEN
  accepted:=accepted||coalesce((SELECT CASE WHEN card.sentence_practice THEN r.sentence_answers ELSE r.word_answers END
   FROM vocabulary_private.sitov_legacy_card_revisions r WHERE r.card_id=card.id),ARRAY[]::text[]);
 END IF;
 IF nullif(btrim(canonical),'') IS NULL THEN RAISE EXCEPTION 'exercise_unavailable' USING ERRCODE='23514'; END IF;$after$;
  IF strpos(definition,before_text)=0 THEN RAISE EXCEPTION 'sitov_legacy_answer_key_source_drift' USING ERRCODE='23514'; END IF;
  EXECUTE replace(definition,before_text,after_text);
 END IF;
 FOREACH signature IN ARRAY ARRAY['vocabulary_private.submit_answer(uuid,boolean,text,text)','vocabulary_private.check_retry_answer(uuid,text,text)'] LOOP
  definition:=pg_get_functiondef(signature::regprocedure);
  IF strpos(definition,'-- sitov-legacy-vocabulary-article-v1')>0 THEN CONTINUE; END IF;
  before_text:=$before$ IF progress.direction='native_to_de' AND NOT card.sentence_practice THEN$before$;
  after_text:=$after$ -- sitov-legacy-vocabulary-article-v1
 IF progress.direction='native_to_de' AND NOT card.sentence_practice
  AND NOT EXISTS(SELECT 1 FROM vocabulary_private.sitov_legacy_card_revisions r
   WHERE r.card_id=card.id AND grade->>'matched'=ANY(r.word_answers)) THEN$after$;
  IF strpos(definition,before_text)=0 THEN RAISE EXCEPTION 'sitov_legacy_article_source_drift' USING ERRCODE='23514'; END IF;
  EXECUTE replace(definition,before_text,after_text);
 END LOOP;
END $historic_answers$;

-- Extend the shared source extractor: CMS and seed imports use the same exact
-- German word, usage chunk and example. Keep the helper's original OID/ACL.
DO $audio$ DECLARE definition text; before_text text; after_text text; BEGIN
 definition:=pg_get_functiondef('learning_private.sitov_learning_audio_texts(text,jsonb,jsonb)'::regprocedure);
 IF strpos(definition,'-- sitov-vocabulary-chunk-audio-v1')>0 THEN RETURN; END IF;
 before_text:=$before$  IF jsonb_typeof(p_translations)='array' THEN$before$;
 after_text:=$after$  -- sitov-vocabulary-chunk-audio-v1
  IF jsonb_typeof(p_fields->'chunk_de')='string' THEN
   texts:=array_append(texts,p_fields->>'chunk_de');
  END IF;
  IF jsonb_typeof(p_translations)='array' THEN$after$;
 IF strpos(definition,before_text)=0 THEN RAISE EXCEPTION 'sitov_chunk_audio_source_drift' USING ERRCODE='23514'; END IF;
 EXECUTE replace(definition,before_text,after_text);
END $audio$;

-- The standard staff editor preserves omitted card fields through its existing
-- merge. Include localized chunks before the publication proof reads the row.
DO $cms$ DECLARE definition text; before_text text; after_text text; BEGIN
 definition:=pg_get_functiondef('public.save_learning_content(text,jsonb,uuid)'::regprocedure);
 IF strpos(definition,'-- sitov-vocabulary-chunk-cms-v1')>0 THEN RETURN; END IF;
 before_text:=$before$  DELETE FROM public.vocabulary_translations WHERE card_id=item;$before$;
 after_text:=$after$  -- sitov-vocabulary-chunk-cms-v1
  UPDATE public.learning_vocabulary_cards SET content_kind=coalesce(fields->>'content_kind','vocabulary'),
   chunk_de=nullif(btrim(fields->>'chunk_de'),'') WHERE id=item;
  -- Older CMS callers may omit this additive field. Preserve it per locale;
  -- an explicit null still clears it. Merge before existing translation cleanup.
  SELECT coalesce(jsonb_agg(CASE WHEN t ? 'chunk_translation' THEN t ELSE
   t || jsonb_build_object('chunk_translation',stored.chunk_translation) END),'[]'::jsonb) INTO translations
   FROM jsonb_array_elements(translations) t LEFT JOIN public.vocabulary_translations stored
    ON stored.card_id=item AND stored.locale=t->>'locale';
  DELETE FROM public.vocabulary_translations WHERE card_id=item;$after$;
 IF strpos(definition,before_text)=0 THEN RAISE EXCEPTION 'sitov_chunk_cms_source_drift' USING ERRCODE='23514'; END IF;
 definition:=replace(definition,before_text,after_text);
 before_text:=$before$INSERT INTO public.vocabulary_translations(card_id,locale,translation,context_sentence,is_difficult)
   VALUES(item,translation_row->>'locale',translation_row->>'translation',translation_row->>'context_sentence',coalesce((translation_row->>'is_difficult')::boolean,false));$before$;
 after_text:=$after$INSERT INTO public.vocabulary_translations(card_id,locale,translation,context_sentence,is_difficult,chunk_translation)
   VALUES(item,translation_row->>'locale',translation_row->>'translation',translation_row->>'context_sentence',coalesce((translation_row->>'is_difficult')::boolean,false),translation_row->>'chunk_translation');$after$;
 IF strpos(definition,before_text)=0 THEN RAISE EXCEPTION 'sitov_chunk_translation_cms_source_drift' USING ERRCODE='23514'; END IF;
 EXECUTE replace(definition,before_text,after_text);
END $cms$;

CREATE OR REPLACE FUNCTION public.sitov_import_vocabulary_seed(p_seed jsonb,p_publish boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path TO '' AS $$
DECLARE unit_data jsonb; card_data jsonb; localized jsonb; lang text; target_unit uuid; target_card uuid;
 existing_card public.learning_vocabulary_cards; preserve_core boolean; unit_count integer:=0; card_count integer:=0;
 vocabulary_count integer:=0; chunk_count integer:=0; reused_count integer:=0; source_key text; word text; selected_article text;
 unit_results jsonb:='[]'::jsonb; card_results jsonb; kind text; chunk text;
 legacy_baseline jsonb; current_baseline jsonb; replacement_fields jsonb; historical vocabulary_private.sitov_legacy_card_revisions;
 revision_applied boolean; old_context text; old_word text; old_plural text; historical_words text[];
BEGIN
 -- Direct database role, never a user-editable JWT claim. No student/staff
 -- callable privileged bridge: this API is only for trusted local seed imports.
 IF current_user NOT IN('service_role','postgres','supabase_admin') THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501'; END IF;
 IF p_publish IS NULL OR jsonb_typeof(p_seed) IS DISTINCT FROM 'object' OR p_seed->>'version' IS DISTINCT FROM '1'
  OR jsonb_typeof(p_seed->'units') IS DISTINCT FROM 'array' OR jsonb_array_length(p_seed->'units') NOT BETWEEN 1 AND 100 THEN
  RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_seed->'units') u GROUP BY u->>'level',u->>'label' HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_seed->'units') u CROSS JOIN LATERAL jsonb_array_elements(u->'cards') c GROUP BY c->>'source_id' HAVING count(*)>1)
  OR (SELECT count(*) FROM jsonb_array_elements(p_seed->'units') u CROSS JOIN LATERAL jsonb_array_elements(u->'cards') c)>10000 THEN
  RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sitov-vocabulary-seed',0));
 FOR unit_data IN SELECT value FROM jsonb_array_elements(p_seed->'units') LOOP
  IF jsonb_typeof(unit_data) IS DISTINCT FROM 'object' OR unit_data->>'level' IS NULL OR unit_data->>'level' NOT IN('A1.1','A1.2','A2.1','A2.2','B1.1','B1.2')
   OR nullif(btrim(unit_data->>'label'),'') IS NULL OR unit_data->>'label'='Eigene Wörter'
   OR length(unit_data->>'label')>200 OR jsonb_typeof(unit_data->'cards') IS DISTINCT FROM 'array'
   OR jsonb_array_length(unit_data->'cards') NOT BETWEEN 1 AND 1000 THEN
   RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
  SELECT u.id INTO target_unit FROM public.learning_units u WHERE u.level=unit_data->>'level' AND u.trainer='vocabulary'
   AND u.label=unit_data->>'label' AND u.owner_auth_user_id IS NULL FOR UPDATE;
  IF target_unit IS NULL THEN
   target_unit:=(unit_data->>'id')::uuid;
   INSERT INTO public.learning_units(id,level,trainer,label,sort_order,is_active)
    VALUES(target_unit,unit_data->>'level','vocabulary',unit_data->>'label',(unit_data->>'sort_order')::integer,p_publish);
  ELSE
   -- A draft import never makes previously active content unavailable.
   UPDATE public.learning_units SET is_active=is_active OR p_publish WHERE id=target_unit;
  END IF;
  card_results:='[]'::jsonb;
  FOR card_data IN SELECT value FROM jsonb_array_elements(unit_data->'cards') LOOP
   source_key:=card_data->>'source_id'; word:=btrim(card_data->>'word_de'); kind:=card_data->>'content_kind';
   selected_article:=nullif(card_data->>'article','none'); chunk:=nullif(btrim(card_data->>'chunk_de'),'');
   IF jsonb_typeof(card_data) IS DISTINCT FROM 'object' OR jsonb_typeof(card_data->'source_id') IS DISTINCT FROM 'string' OR nullif(source_key,'') IS NULL OR length(source_key)>160
    OR word IS NULL OR length(word) NOT BETWEEN 1 AND 500 OR kind IS NULL OR kind NOT IN('vocabulary','chunk')
    OR (selected_article IS NOT NULL AND selected_article NOT IN('der','die','das')) OR (kind='chunk' AND selected_article IS NOT NULL)
    OR NOT learning_private.german_text_allowed(word) OR NOT learning_private.german_text_allowed(chunk)
    OR jsonb_typeof(card_data->'sentence_practice') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(card_data->'translations') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
   FOREACH lang IN ARRAY ARRAY['de','en','ru','uk','tr'] LOOP
    localized:=card_data->'translations'->lang;
    IF jsonb_typeof(localized) IS DISTINCT FROM 'object' OR nullif(btrim(localized->>'context_sentence'),'') IS NULL
     OR (lang<>'de' AND nullif(btrim(localized->>'translation'),'') IS NULL)
     OR (lang<>'de' AND chunk IS NOT NULL AND nullif(btrim(localized->>'chunk_translation'),'') IS NULL) THEN
     RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
    IF lang='de' AND NOT learning_private.german_text_allowed(localized->>'context_sentence') THEN
     RAISE EXCEPTION 'invalid_vocabulary_seed' USING ERRCODE='22023'; END IF;
   END LOOP;
   SELECT c.* INTO existing_card FROM public.learning_vocabulary_cards c WHERE c.source_id=source_key FOR UPDATE;
   IF existing_card.id IS NULL THEN
    SELECT c.* INTO existing_card FROM public.learning_vocabulary_cards c WHERE c.id=(card_data->>'id')::uuid FOR UPDATE;
   END IF;
   IF existing_card.id IS NULL THEN
    IF (SELECT count(*) FROM public.learning_vocabulary_cards c WHERE c.unit_id=target_unit AND c.source_id IS NULL
     AND lower(btrim(c.word_de))=lower(word) AND coalesce(nullif(c.article::text,'none'),'')=coalesce(selected_article,''))>1 THEN
     RAISE EXCEPTION 'ambiguous_vocabulary_identity' USING ERRCODE='23514'; END IF;
    SELECT c.* INTO existing_card FROM public.learning_vocabulary_cards c WHERE c.unit_id=target_unit AND c.source_id IS NULL
     AND lower(btrim(c.word_de))=lower(word) AND coalesce(nullif(c.article::text,'none'),'')=coalesce(selected_article,'') FOR UPDATE;
   END IF;
   IF existing_card.id IS NULL THEN
    IF card_data ? 'legacy_revision' THEN RAISE EXCEPTION 'legacy_revision_requires_existing_card' USING ERRCODE='23514'; END IF;
    target_card:=(card_data->>'id')::uuid; preserve_core:=false; revision_applied:=false;
    INSERT INTO public.learning_vocabulary_cards(id,unit_id,word_de,article,plural,sentence_practice,alternative_answers_de,target_form,content_kind,chunk_de,source_id)
     VALUES(target_card,target_unit,word,selected_article::public.grammatical_article,card_data->>'plural',(card_data->>'sentence_practice')::boolean,
      ARRAY(SELECT jsonb_array_elements_text(coalesce(card_data->'alternative_answers_de','[]'::jsonb))),
      CASE WHEN card_data->'target_form' IS NULL OR card_data->'target_form'='null'::jsonb THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text(card_data->'target_form')) END,
      kind,chunk,source_key);
    INSERT INTO vocabulary_private.sitov_seed_card_origins(card_id,preserve_core) VALUES(target_card,false);
   ELSE
    target_card:=existing_card.id;
    IF existing_card.unit_id<>target_unit OR (existing_card.source_id IS NOT NULL AND existing_card.source_id<>source_key) THEN
     RAISE EXCEPTION 'vocabulary_identity_conflict' USING ERRCODE='23514'; END IF;
    INSERT INTO vocabulary_private.sitov_seed_card_origins(card_id,preserve_core) VALUES(target_card,true) ON CONFLICT(card_id) DO NOTHING;
    SELECT o.preserve_core INTO preserve_core FROM vocabulary_private.sitov_seed_card_origins o WHERE o.card_id=target_card;
    revision_applied:=false;
    IF card_data ? 'legacy_revision' THEN
     legacy_baseline:=card_data->'legacy_revision';
     IF legacy_baseline->>'article'='none' THEN legacy_baseline:=jsonb_set(legacy_baseline,'{article}','null'::jsonb); END IF;
     IF NOT preserve_core OR jsonb_typeof(legacy_baseline) IS DISTINCT FROM 'object'
      OR NOT(legacy_baseline ?& ARRAY['word_de','article','context_sentence_de'])
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(legacy_baseline) k WHERE k NOT IN('word_de','article','context_sentence_de')) THEN
      RAISE EXCEPTION 'invalid_legacy_revision' USING ERRCODE='23514'; END IF;
     SELECT t.context_sentence INTO old_context FROM public.vocabulary_translations t WHERE t.card_id=target_card AND t.locale='de' FOR UPDATE;
     current_baseline:=jsonb_build_object('word_de',existing_card.word_de,'article',nullif(existing_card.article::text,'none'),'context_sentence_de',old_context);
     replacement_fields:=jsonb_build_object('word_de',word,'article',selected_article,'context_sentence_de',card_data->'translations'->'de'->>'context_sentence');
     SELECT r.* INTO historical FROM vocabulary_private.sitov_legacy_card_revisions r WHERE r.card_id=target_card FOR UPDATE;
     IF current_baseline=legacy_baseline THEN
      old_word:=concat_ws(' ',nullif(existing_card.article::text,'none'),existing_card.word_de);
      historical_words:=ARRAY[old_word]; old_plural:=nullif(btrim(existing_card.plural),'');
      IF nullif(existing_card.article::text,'none') IS NOT NULL AND old_plural IS NOT NULL AND old_plural NOT IN('-','–','—') THEN
       historical_words:=historical_words||('die '||old_plural)||(old_word||' / die '||old_plural)||(old_word||', die '||old_plural);
      END IF;
      INSERT INTO vocabulary_private.sitov_legacy_card_revisions(card_id,baseline,replacement,word_answers,sentence_answers)
       VALUES(target_card,legacy_baseline,replacement_fields,historical_words,CASE WHEN nullif(btrim(old_context),'') IS NULL THEN ARRAY[]::text[] ELSE ARRAY[old_context] END)
       ON CONFLICT(card_id) DO UPDATE SET baseline=excluded.baseline,replacement=excluded.replacement,
        word_answers=sitov_legacy_card_revisions.word_answers||ARRAY(SELECT x FROM unnest(excluded.word_answers) x WHERE NOT x=ANY(sitov_legacy_card_revisions.word_answers)),
        sentence_answers=sitov_legacy_card_revisions.sentence_answers||ARRAY(SELECT x FROM unnest(excluded.sentence_answers) x WHERE NOT x=ANY(sitov_legacy_card_revisions.sentence_answers));
     ELSIF historical.card_id IS NULL OR legacy_baseline IS DISTINCT FROM historical.baseline
      OR replacement_fields IS DISTINCT FROM historical.replacement OR current_baseline IS DISTINCT FROM historical.replacement THEN
      RAISE EXCEPTION 'stale_legacy_revision' USING ERRCODE='23514';
     END IF;
     revision_applied:=true;
    END IF;
    UPDATE public.learning_vocabulary_cards SET content_kind=kind,chunk_de=chunk,source_id=source_key,
     word_de=CASE WHEN preserve_core AND NOT revision_applied THEN word_de ELSE word END,
     article=CASE WHEN preserve_core AND NOT revision_applied THEN learning_vocabulary_cards.article ELSE selected_article::public.grammatical_article END,
     plural=CASE WHEN preserve_core AND NOT revision_applied THEN plural ELSE card_data->>'plural' END,
     target_form=CASE WHEN revision_applied THEN CASE WHEN card_data->'target_form' IS NULL OR card_data->'target_form'='null'::jsonb THEN NULL
      ELSE ARRAY(SELECT jsonb_array_elements_text(card_data->'target_form')) END ELSE target_form END
     WHERE id=target_card;
    -- Accepted answers and sentence_practice never change for existing cards.
    -- Only an explicit baseline-checked revision updates displayed target
    -- forms; historical answers stay in their original/private arrays.
    reused_count:=reused_count+1;
   END IF;
   FOREACH lang IN ARRAY ARRAY['de','en','ru','uk','tr'] LOOP
    localized:=card_data->'translations'->lang;
    INSERT INTO public.vocabulary_translations(card_id,locale,translation,context_sentence,chunk_translation)
     VALUES(target_card,lang,localized->>'translation',localized->>'context_sentence',localized->>'chunk_translation')
     ON CONFLICT(card_id,locale) DO UPDATE SET chunk_translation=excluded.chunk_translation,
      translation=CASE WHEN preserve_core AND NOT revision_applied THEN vocabulary_translations.translation ELSE excluded.translation END,
      context_sentence=CASE WHEN preserve_core AND NOT revision_applied THEN vocabulary_translations.context_sentence ELSE excluded.context_sentence END;
   END LOOP;
   -- Reads stored authoritative fields + translations. Active targets require
   -- male Qwen profile, exact text, valid Storage object and full word timings.
   PERFORM learning_private.sitov_require_prepared_learning_audio('vocabulary',jsonb_build_object('id',target_card),'[]'::jsonb,target_unit);
   card_results:=card_results||jsonb_build_array(jsonb_build_object('source_id',source_key,'card_id',target_card));
   card_count:=card_count+1;
   IF kind='chunk' THEN chunk_count:=chunk_count+1; ELSE vocabulary_count:=vocabulary_count+1; END IF;
  END LOOP;
  unit_results:=unit_results||jsonb_build_array(jsonb_build_object('unit_id',target_unit,'level',unit_data->>'level','label',unit_data->>'label','cards',card_results));
  unit_count:=unit_count+1;
 END LOOP;
 RETURN jsonb_build_object('unit_count',unit_count,'card_count',card_count,'vocabulary_count',vocabulary_count,'chunk_count',chunk_count,'reused_count',reused_count,'published',p_publish,'units',unit_results);
 EXCEPTION WHEN OTHERS THEN
  -- The exception block rolls back the entire seed, including activation and
  -- inserted cards. Fixed errors only; no answers or protected metadata leak.
  RETURN jsonb_build_object('error',CASE WHEN SQLERRM='prepared_audio_required' THEN 'prepared_audio_required'
   WHEN SQLSTATE='42501' THEN 'not_authorized' ELSE 'invalid_vocabulary_seed' END);
END $$;
REVOKE ALL ON FUNCTION public.sitov_import_vocabulary_seed(jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_import_vocabulary_seed(jsonb,boolean) TO service_role;

-- END SITOV VOCABULARY CHUNKS IMPORT

-- BEGIN SITOV EXAM PREPARATION
-- Global B1 exam preparation. Durable server-graded receipts and private submissions.
-- No teacher is inferred from a note author or from a course registration.
CREATE SCHEMA IF NOT EXISTS sitov_exam_private;
REVOKE ALL ON SCHEMA sitov_exam_private FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA sitov_exam_private TO authenticated,service_role;

CREATE TABLE IF NOT EXISTS public.sitov_exam_profiles (
 student_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 profile_id text NOT NULL DEFAULT 'general_b1' CHECK(profile_id IN ('general_b1','dtz_a2_b1','telc_deutsch_b1','goethe_b1','oesd_zb1','telc_deutsch_a2_b1','oesd_zdoe_b1')),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.sitov_exam_teacher_assignments (
 student_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 teacher_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 response_days integer NOT NULL DEFAULT 7 CHECK(response_days BETWEEN 1 AND 90),
 assigned_by uuid NOT NULL,
 updated_at timestamptz NOT NULL DEFAULT now(), CHECK(student_id<>teacher_id)
);
CREATE INDEX IF NOT EXISTS sitov_exam_assignment_teacher_idx ON public.sitov_exam_teacher_assignments(teacher_id);
CREATE TABLE IF NOT EXISTS public.sitov_exam_attempts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 task_id text NOT NULL, task_version integer NOT NULL CHECK(task_version>0), unit_id text NOT NULL,
 answer jsonb NOT NULL CHECK(jsonb_typeof(answer) IN('string','array') AND octet_length(answer::text)<=20000),
 correct boolean, helped boolean NOT NULL DEFAULT false, feedback_viewed boolean NOT NULL DEFAULT false,
 seconds integer NOT NULL DEFAULT 0 CHECK(seconds BETWEEN 0 AND 7200), mode text NOT NULL CHECK(mode IN('practice','checkpoint')),
 variant integer NOT NULL DEFAULT 0 CHECK(variant BETWEEN 0 AND 99), request_id uuid NOT NULL,
 feedback jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,request_id)
);
CREATE INDEX IF NOT EXISTS sitov_exam_attempt_student_idx ON public.sitov_exam_attempts(student_id,created_at);
CREATE TABLE IF NOT EXISTS public.sitov_exam_hints (
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 task_id text NOT NULL, task_version integer NOT NULL CHECK(task_version>0), created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(student_id,task_id,task_version)
);
CREATE TABLE IF NOT EXISTS public.sitov_exam_submissions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 task_id text NOT NULL, task_version integer NOT NULL CHECK(task_version>0), unit_id text NOT NULL,
 request_id uuid NOT NULL DEFAULT gen_random_uuid(), explicit_submit boolean NOT NULL DEFAULT false,
 kind text NOT NULL CHECK(kind IN('writing','speaking')), helped boolean NOT NULL DEFAULT false, text_content text NOT NULL DEFAULT '' CHECK(length(text_content)<=20000),
 media_path text, photo_path text, teacher_id uuid,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','reviewed')),
 previous_id uuid REFERENCES public.sitov_exam_submissions(id) ON DELETE SET NULL,
 reflection text CHECK(length(reflection)<=5000), created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(status='draft' OR teacher_id IS NOT NULL),
 CHECK(media_path IS NULL OR media_path LIKE student_id::text||'/%'),
 CHECK(photo_path IS NULL OR photo_path LIKE student_id::text||'/%'),
 CHECK(length(trim(text_content))>0 OR media_path IS NOT NULL OR photo_path IS NOT NULL), CHECK(previous_id IS DISTINCT FROM id), UNIQUE(student_id,request_id)
);
CREATE INDEX IF NOT EXISTS sitov_exam_submission_student_idx ON public.sitov_exam_submissions(student_id,created_at);
CREATE INDEX IF NOT EXISTS sitov_exam_submission_teacher_idx ON public.sitov_exam_submissions(teacher_id,status,created_at);
CREATE TABLE IF NOT EXISTS public.sitov_exam_feedback (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES public.sitov_exam_submissions(id) ON DELETE CASCADE,
 teacher_id uuid NOT NULL, text_content text NOT NULL CHECK(length(trim(text_content)) BETWEEN 1 AND 10000),
 strengths text NOT NULL CHECK(length(strengths)<=5000), priorities jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(priorities)='array' AND jsonb_array_length(priorities)<=2),
 revision text NOT NULL CHECK(length(trim(revision)) BETWEEN 1 AND 5000), rating text NOT NULL CHECK(rating IN('practice','assisted','independent')),
 rubric jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(rubric)='array'), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sitov_exam_feedback_submission_idx ON public.sitov_exam_feedback(submission_id,created_at);
CREATE TABLE IF NOT EXISTS public.sitov_exam_unlocks (
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 module_id text NOT NULL, kind text NOT NULL CHECK(kind IN('teacher','fallback')),
 reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 5000), created_by uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(student_id,module_id,kind)
);
CREATE TABLE IF NOT EXISTS public.sitov_exam_audio_productions (
 audio_id text PRIMARY KEY, script_hash text NOT NULL, raw_path text, prepared_path text, raw_filename text, prepared_filename text,
 status text NOT NULL DEFAULT 'briefing' CHECK(status IN('briefing','script_review','ready_to_record','awaiting_recording','uploaded','reviewed','published')),
 created_by uuid NOT NULL, reviewed_by uuid,
 word_timings jsonb CHECK(word_timings IS NULL OR jsonb_typeof(word_timings)='array'), review_note text,
 reviewed_at timestamptz, published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(status NOT IN('reviewed','published') OR (prepared_path IS NOT NULL AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND length(trim(review_note))>0 AND coalesce(jsonb_array_length(word_timings),0)>0)),
 CHECK(status<>'published' OR published_at IS NOT NULL)
);

-- Historical authors, recipients and reviewers are immutable audit UUIDs.
-- Deleting a retired staff profile must preserve learner feedback and shared
-- human recordings. Live access always requires a profile and an assignment;
-- insert validation still requires a real, authorized staff member.
ALTER TABLE public.sitov_exam_teacher_assignments DROP CONSTRAINT IF EXISTS sitov_exam_teacher_assignments_assigned_by_fkey;
ALTER TABLE public.sitov_exam_submissions DROP CONSTRAINT IF EXISTS sitov_exam_submissions_teacher_id_fkey;
ALTER TABLE public.sitov_exam_feedback DROP CONSTRAINT IF EXISTS sitov_exam_feedback_teacher_id_fkey;
ALTER TABLE public.sitov_exam_unlocks DROP CONSTRAINT IF EXISTS sitov_exam_unlocks_created_by_fkey;
ALTER TABLE public.sitov_exam_audio_productions DROP CONSTRAINT IF EXISTS sitov_exam_audio_productions_created_by_fkey;
ALTER TABLE public.sitov_exam_audio_productions DROP CONSTRAINT IF EXISTS sitov_exam_audio_productions_reviewed_by_fkey;

-- Private ACL helper: authorization always derives from profiles and explicit assignments.
CREATE OR REPLACE FUNCTION sitov_exam_private.has_access(p_student uuid DEFAULT auth.uid()) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT (SELECT auth.uid()) IS NOT NULL AND p_student=(SELECT auth.uid()) AND EXISTS(
 SELECT 1 FROM public.profiles p WHERE p.id=p_student AND (p.role IN('teacher','admin') OR EXISTS(
 SELECT 1 FROM public.student_level_access a WHERE a.auth_user_id=p.id AND a.level IN('B1.1','B1.2'))));
$$;
CREATE OR REPLACE FUNCTION sitov_exam_private.can_read(p_student uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT (SELECT auth.uid()) IS NOT NULL AND (
 (p_student=(SELECT auth.uid()) AND sitov_exam_private.has_access()) OR
 EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=(SELECT auth.uid()) AND (p.role='admin' OR (p.role='teacher' AND EXISTS(
 SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=p_student AND a.teacher_id=p.id)))));
$$;
CREATE OR REPLACE FUNCTION sitov_exam_private.is_staff() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid()) AND role IN('admin','teacher'));
$$;
CREATE OR REPLACE FUNCTION sitov_exam_private.is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid()) AND role='admin');
$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA sitov_exam_private FROM PUBLIC,anon;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA sitov_exam_private TO authenticated,service_role;

CREATE OR REPLACE FUNCTION sitov_exam_private.validate_assignment() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.teacher_id AND role IN('teacher','admin')) OR
 NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.assigned_by AND role='admin') THEN RAISE check_violation USING message='invalid_exam_teacher_assignment'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_exam_assignment_valid ON public.sitov_exam_teacher_assignments;
CREATE TRIGGER sitov_exam_assignment_valid BEFORE INSERT OR UPDATE ON public.sitov_exam_teacher_assignments FOR EACH ROW EXECUTE FUNCTION sitov_exam_private.validate_assignment();
CREATE OR REPLACE FUNCTION sitov_exam_private.validate_submission() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF NEW.previous_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sitov_exam_submissions s WHERE s.id=NEW.previous_id AND s.student_id=NEW.student_id AND s.task_id=NEW.task_id AND s.unit_id=NEW.unit_id AND s.kind=NEW.kind) THEN RAISE check_violation USING message='invalid_exam_revision'; END IF;
 IF NEW.status<>'draft' AND NOT EXISTS(SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=NEW.student_id AND a.teacher_id=NEW.teacher_id) THEN RAISE check_violation USING message='missing_exam_recipient'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_exam_submission_valid ON public.sitov_exam_submissions;
CREATE TRIGGER sitov_exam_submission_valid BEFORE INSERT OR UPDATE ON public.sitov_exam_submissions FOR EACH ROW EXECUTE FUNCTION sitov_exam_private.validate_submission();


CREATE OR REPLACE FUNCTION sitov_exam_private.validate_feedback() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$ DECLARE target public.sitov_exam_submissions; BEGIN
 SELECT * INTO target FROM public.sitov_exam_submissions WHERE id=NEW.submission_id FOR UPDATE;
 IF target.id IS NULL OR target.status='draft' OR NOT EXISTS(
 SELECT 1 FROM public.profiles p WHERE p.id=NEW.teacher_id AND (p.role='admin' OR (p.role='teacher' AND target.teacher_id=p.id AND EXISTS(
 SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=target.student_id AND a.teacher_id=p.id))))
 THEN RAISE check_violation USING message='unauthorized_exam_feedback'; END IF;
 IF NEW.rating='independent' AND target.helped THEN RAISE check_violation USING message='assisted_exam_submission'; END IF;
 UPDATE public.sitov_exam_submissions SET status='reviewed' WHERE id=target.id;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_exam_feedback_valid ON public.sitov_exam_feedback;
CREATE TRIGGER sitov_exam_feedback_valid BEFORE INSERT ON public.sitov_exam_feedback FOR EACH ROW EXECUTE FUNCTION sitov_exam_private.validate_feedback();

DO $$ DECLARE name text; BEGIN
 FOREACH name IN ARRAY ARRAY['sitov_exam_profiles','sitov_exam_teacher_assignments','sitov_exam_attempts','sitov_exam_hints','sitov_exam_submissions','sitov_exam_feedback','sitov_exam_unlocks','sitov_exam_audio_productions'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',name);
 EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',name);
 EXECUTE format('GRANT SELECT ON public.%I TO authenticated',name);
 EXECUTE format('GRANT ALL ON public.%I TO service_role',name);
 END LOOP;
END $$;
