-- END SITOV EXAM PREPARATION

-- BEGIN SITOV EXAM SIMULATION
-- Sitov Academy: independently persisted exam rehearsals and released simulations.
-- Frozen task keys remain server-only. Existing preparation receipts are untouched.
CREATE SCHEMA IF NOT EXISTS sitov_simulation_private;
REVOKE ALL ON SCHEMA sitov_simulation_private FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA sitov_simulation_private TO service_role;
-- Advanced simulation permissions are independent from existing A1–B1 trainers.
CREATE TABLE IF NOT EXISTS public.sitov_simulation_level_grants (
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 level text NOT NULL CHECK(level IN('B2','C1','C2')),
 granted_by uuid NOT NULL,
 granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(student_id,level)
);
ALTER TABLE public.sitov_simulation_level_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sitov_simulation_level_grants FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.sitov_simulation_level_grants TO service_role;
CREATE OR REPLACE FUNCTION sitov_simulation_private.validate_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.student_id AND role='student')
 OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.granted_by AND (p.role='admin' OR (p.role='teacher' AND EXISTS(
  SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=NEW.student_id AND a.teacher_id=NEW.granted_by))))
 THEN RAISE EXCEPTION 'unauthorized_simulation_level_grant' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_simulation_grant_valid ON public.sitov_simulation_level_grants;
CREATE TRIGGER sitov_simulation_grant_valid BEFORE INSERT OR UPDATE ON public.sitov_simulation_level_grants FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.validate_grant();
CREATE TABLE IF NOT EXISTS public.sitov_simulation_runs (
 id uuid PRIMARY KEY,
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 level text NOT NULL CHECK(level IN('A1','A2','B1','B2','C1','C2')),
 provider text NOT NULL CHECK(provider IN('sitov','telc','goethe','oesd','dtz')),
 mode text NOT NULL CHECK(mode IN('practice','exam')),
 status text NOT NULL CHECK(status IN('active','completed')),
 started_at timestamptz NOT NULL,
 expires_at timestamptz NOT NULL,
 completed_at timestamptz,
 revision integer NOT NULL DEFAULT 0 CHECK(revision>=0),
 start_request_id uuid NOT NULL,
 start_request_hash text NOT NULL,
 server_snapshot jsonb NOT NULL CHECK(jsonb_typeof(server_snapshot)='object' AND octet_length(server_snapshot::text)<=1000000),
 UNIQUE(student_id,start_request_id),
 CHECK(expires_at>started_at),
 CHECK((status='active' AND completed_at IS NULL) OR (status='completed' AND completed_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS sitov_simulation_student_history_idx ON public.sitov_simulation_runs(student_id,started_at DESC,id);
-- An active rehearsal is resumed rather than silently replaced on another device.
CREATE UNIQUE INDEX IF NOT EXISTS sitov_simulation_one_active_idx ON public.sitov_simulation_runs(student_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS public.sitov_simulation_receipts (
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 request_id uuid NOT NULL,
 run_id uuid NOT NULL REFERENCES public.sitov_simulation_runs(id) ON DELETE CASCADE,
 kind text NOT NULL CHECK(kind IN('answer','finish','review')),
 payload_hash text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(student_id,request_id)
);
ALTER TABLE public.sitov_simulation_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sitov_simulation_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sitov_simulation_runs,public.sitov_simulation_receipts FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.sitov_simulation_runs,public.sitov_simulation_receipts TO service_role;

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_run() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 PERFORM learning_reset_private.assert_writable(NEW.student_id);
 IF NEW.server_snapshot->>'id' IS DISTINCT FROM NEW.id::text
 OR NEW.server_snapshot->>'level' IS DISTINCT FROM NEW.level
 OR NEW.server_snapshot->>'provider' IS DISTINCT FROM NEW.provider
 OR NEW.server_snapshot->>'mode' IS DISTINCT FROM NEW.mode
 OR NEW.server_snapshot->>'status' IS DISTINCT FROM NEW.status
 OR (NEW.server_snapshot->>'startedAt')::timestamptz IS DISTINCT FROM NEW.started_at
 OR (NEW.server_snapshot->>'expiresAt')::timestamptz IS DISTINCT FROM NEW.expires_at
 OR (NEW.server_snapshot->>'completedAt')::timestamptz IS DISTINCT FROM NEW.completed_at
 OR jsonb_typeof(NEW.server_snapshot->'tasks') IS DISTINCT FROM 'array'
 OR jsonb_array_length(NEW.server_snapshot->'tasks')=0
 OR jsonb_typeof(NEW.server_snapshot->'answers') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'invalid_simulation_snapshot' USING ERRCODE='23514'; END IF;
 IF NEW.provider='sitov' AND NEW.mode='exam' AND (
  NEW.server_snapshot->'coverage'->>'fullExam' IS DISTINCT FROM 'true'
  OR jsonb_typeof(NEW.server_snapshot->'coverage'->'missing') IS DISTINCT FROM 'array'
  OR jsonb_array_length(NEW.server_snapshot->'coverage'->'missing')<>0)
 THEN RAISE EXCEPTION 'incomplete_universal_simulation' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.student_id,NEW.level,NEW.provider,NEW.mode,NEW.started_at,NEW.expires_at,NEW.start_request_id,NEW.start_request_hash)
    IS DISTINCT FROM ROW(OLD.id,OLD.student_id,OLD.level,OLD.provider,OLD.mode,OLD.started_at,OLD.expires_at,OLD.start_request_id,OLD.start_request_hash)
   OR NEW.server_snapshot->'version' IS DISTINCT FROM OLD.server_snapshot->'version'
   OR NEW.server_snapshot->'profileId' IS DISTINCT FROM OLD.server_snapshot->'profileId'
   OR NEW.server_snapshot->'tasks' IS DISTINCT FROM OLD.server_snapshot->'tasks'
   OR NEW.server_snapshot->'coverage' IS DISTINCT FROM OLD.server_snapshot->'coverage'
   OR NEW.server_snapshot->'rubric' IS DISTINCT FROM OLD.server_snapshot->'rubric'
   OR NEW.revision<>OLD.revision+1
  THEN RAISE EXCEPTION 'immutable_simulation_assignment' USING ERRCODE='23514'; END IF;
  IF OLD.status='completed' AND (NEW.status<>'completed' OR NEW.completed_at IS DISTINCT FROM OLD.completed_at OR NEW.server_snapshot->'answers' IS DISTINCT FROM OLD.server_snapshot->'answers')
  THEN RAISE EXCEPTION 'completed_simulation_is_frozen' USING ERRCODE='23514'; END IF;
  IF clock_timestamp()>=OLD.expires_at AND NEW.server_snapshot->'answers' IS DISTINCT FROM OLD.server_snapshot->'answers'
  THEN RAISE EXCEPTION 'simulation_time_expired' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_simulation_guard ON public.sitov_simulation_runs;
CREATE TRIGGER sitov_simulation_guard BEFORE INSERT OR UPDATE ON public.sitov_simulation_runs FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_run();

-- Only a validated server action can submit a complete server snapshot.
-- Locking, revision comparison and the receipt are atomic, including concurrent devices.
CREATE OR REPLACE FUNCTION public.sitov_store_simulation_change(
 p_run_id uuid,p_student_id uuid,p_revision integer,p_snapshot jsonb,
 p_request_id uuid,p_kind text,p_payload_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE target public.sitov_simulation_runs; receipt public.sitov_simulation_receipts; BEGIN
 -- Same lock order as global learning reset and profile deletion.
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||p_student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 -- The guarded UPDATE below calls assert_writable as the existing reset guard owner.
 SELECT * INTO target FROM public.sitov_simulation_runs WHERE id=p_run_id AND student_id=p_student_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'simulation_not_found' USING ERRCODE='42501'; END IF;
 SELECT * INTO receipt FROM public.sitov_simulation_receipts WHERE student_id=p_student_id AND request_id=p_request_id;
 IF FOUND THEN
  IF receipt.run_id<>p_run_id OR receipt.kind<>p_kind OR receipt.payload_hash<>p_payload_hash
  THEN RAISE EXCEPTION 'simulation_request_reused' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('snapshot',target.server_snapshot,'revision',target.revision,'replayed',true);
 END IF;
 IF target.revision<>p_revision THEN RETURN jsonb_build_object('conflict',true); END IF;
 IF p_kind='answer' AND (target.status<>'active' OR clock_timestamp()>=target.expires_at)
 THEN RAISE EXCEPTION 'simulation_time_expired' USING ERRCODE='55000'; END IF;
 IF p_kind='review' AND target.status<>'completed' THEN RAISE EXCEPTION 'simulation_not_completed' USING ERRCODE='23514'; END IF;
 IF p_kind NOT IN('answer','finish','review') THEN RAISE EXCEPTION 'invalid_simulation_change' USING ERRCODE='23514'; END IF;
 IF (p_kind='answer' AND p_snapshot->>'status' IS DISTINCT FROM 'active')
 OR (p_kind IN('finish','review') AND p_snapshot->>'status' IS DISTINCT FROM 'completed')
 OR (p_kind='finish' AND p_snapshot->'answers' IS DISTINCT FROM target.server_snapshot->'answers')
 THEN RAISE EXCEPTION 'invalid_simulation_transition' USING ERRCODE='23514'; END IF;
 UPDATE public.sitov_simulation_runs SET server_snapshot=p_snapshot,status=p_snapshot->>'status',
  completed_at=(p_snapshot->>'completedAt')::timestamptz,revision=revision+1 WHERE id=p_run_id RETURNING * INTO target;
 INSERT INTO public.sitov_simulation_receipts(student_id,request_id,run_id,kind,payload_hash) VALUES(p_student_id,p_request_id,p_run_id,p_kind,p_payload_hash);
 RETURN jsonb_build_object('snapshot',target.server_snapshot,'revision',target.revision,'replayed',false);
END $$;
REVOKE ALL ON FUNCTION public.sitov_store_simulation_change(uuid,uuid,integer,jsonb,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_store_simulation_change(uuid,uuid,integer,jsonb,uuid,text,text) TO service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA sitov_simulation_private FROM PUBLIC,anon,authenticated,service_role;

-- The established reset also clears rehearsals, without changing preparation IDs.
DO $sitov$ DECLARE body text; marker text:='DELETE FROM public.sitov_exam_submissions'; BEGIN
 body:=pg_get_functiondef('learning_reset_private.finish_reset(uuid)'::regprocedure);
 IF strpos(body,'DELETE FROM public.sitov_simulation_runs')=0 THEN
  IF strpos(body,marker)=0 THEN RAISE EXCEPTION 'sitov_simulation_reset_contract_changed'; END IF;
  EXECUTE replace(body,marker,E'DELETE FROM public.sitov_simulation_runs WHERE student_id=actor;\n  '||marker);
 END IF;
END $sitov$;
NOTIFY pgrst,'reload schema';
-- END SITOV EXAM SIMULATION

-- BEGIN SITOV SIMULATION FEATURE ACCESS
-- Sitov Academy: every learner starts with the simulation feature locked.
-- No existing course or advanced level grant creates a feature grant.
CREATE TABLE IF NOT EXISTS public.sitov_simulation_feature_grants (
 student_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 granted_by uuid NOT NULL,
 granted_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sitov_simulation_feature_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sitov_simulation_feature_grants FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.sitov_simulation_feature_grants TO service_role;

CREATE OR REPLACE FUNCTION sitov_simulation_private.feature_allowed(p_student uuid) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=p_student AND (
  p.role IN('teacher','admin') OR (p.role='student' AND EXISTS(
   SELECT 1 FROM public.sitov_simulation_feature_grants g WHERE g.student_id=p.id))))
$$;
REVOKE ALL ON FUNCTION sitov_simulation_private.feature_allowed(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION sitov_simulation_private.feature_allowed(uuid) TO service_role;

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_feature_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE learner uuid; BEGIN
 learner:=CASE WHEN TG_OP='DELETE' THEN OLD.student_id ELSE NEW.student_id END;
 -- Revoke and answer/upload transactions share a lock, so the latest grant wins.
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||learner::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.student_id AND role='student')
 OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.granted_by AND (p.role='admin' OR (p.role='teacher' AND EXISTS(
  SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=NEW.student_id AND a.teacher_id=NEW.granted_by))))
 THEN RAISE EXCEPTION 'unauthorized_simulation_feature_grant' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_feature_grant() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_feature_grant_guard ON public.sitov_simulation_feature_grants;
CREATE TRIGGER sitov_simulation_feature_grant_guard BEFORE INSERT OR UPDATE OR DELETE ON public.sitov_simulation_feature_grants FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_feature_grant();

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_feature_run() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF TG_OP='INSERT' OR OLD.status='active' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
  IF NOT sitov_simulation_private.feature_allowed(NEW.student_id)
  THEN RAISE EXCEPTION 'simulation_feature_not_granted' USING ERRCODE='42501'; END IF;
 END IF;
 -- Completed answers remain available for assigned staff review after a revoke.
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_feature_run() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_feature_guard ON public.sitov_simulation_runs;
CREATE TRIGGER sitov_simulation_feature_guard BEFORE INSERT OR UPDATE ON public.sitov_simulation_runs FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_feature_run();

-- A previously issued signed upload must also stop working after feature revoke.
-- Existing preparation uploads keep their contract and remain independent.
ALTER TABLE public.sitov_exam_upload_tickets ADD COLUMN IF NOT EXISTS simulation_run_id uuid REFERENCES public.sitov_simulation_runs(id) ON DELETE CASCADE;
CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_feature_ticket() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NEW.simulation_run_id IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
  IF NOT sitov_simulation_private.feature_allowed(NEW.student_id)
  THEN RAISE EXCEPTION 'simulation_feature_not_granted' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sitov_simulation_runs r WHERE r.id=NEW.simulation_run_id AND r.student_id=NEW.student_id AND r.status='active' AND r.expires_at>clock_timestamp())
  THEN RAISE EXCEPTION 'simulation_upload_not_active' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_feature_ticket() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_feature_ticket_guard ON public.sitov_exam_upload_tickets;
CREATE TRIGGER sitov_simulation_feature_ticket_guard BEFORE INSERT OR UPDATE ON public.sitov_exam_upload_tickets FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_feature_ticket();

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_feature_storage() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE learner uuid; simulation uuid; BEGIN
 IF NEW.bucket_id<>'sitov-exam-submissions' THEN RETURN NEW; END IF;
 SELECT t.student_id,t.simulation_run_id INTO learner,simulation FROM public.sitov_exam_upload_tickets t WHERE t.path=NEW.name;
 IF simulation IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||learner::text,0));
  IF NOT sitov_simulation_private.feature_allowed(learner)
  THEN RAISE EXCEPTION 'simulation_feature_not_granted' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sitov_simulation_runs r WHERE r.id=simulation AND r.student_id=learner AND r.status='active' AND r.expires_at>clock_timestamp())
  THEN RAISE EXCEPTION 'simulation_upload_not_active' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_feature_storage() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_feature_storage_guard ON storage.objects;
CREATE TRIGGER sitov_simulation_feature_storage_guard BEFORE INSERT OR UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_feature_storage();

-- Check feature access inside the same transaction, before any receipt replay.
CREATE OR REPLACE FUNCTION public.sitov_store_simulation_change(
 p_run_id uuid,p_student_id uuid,p_revision integer,p_snapshot jsonb,
 p_request_id uuid,p_kind text,p_payload_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE target public.sitov_simulation_runs; receipt public.sitov_simulation_receipts; BEGIN
 -- Same lock order as global learning reset and profile deletion.
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||p_student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 -- The guarded UPDATE below calls assert_writable as the existing reset guard owner.
 SELECT * INTO target FROM public.sitov_simulation_runs WHERE id=p_run_id AND student_id=p_student_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'simulation_not_found' USING ERRCODE='42501'; END IF;
 IF p_kind IN('answer','finish') AND NOT sitov_simulation_private.feature_allowed(p_student_id)
 THEN RAISE EXCEPTION 'simulation_feature_not_granted' USING ERRCODE='42501'; END IF;
 SELECT * INTO receipt FROM public.sitov_simulation_receipts WHERE student_id=p_student_id AND request_id=p_request_id;
 IF FOUND THEN
  IF receipt.run_id<>p_run_id OR receipt.kind<>p_kind OR receipt.payload_hash<>p_payload_hash
  THEN RAISE EXCEPTION 'simulation_request_reused' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('snapshot',target.server_snapshot,'revision',target.revision,'replayed',true);
 END IF;
 IF target.revision<>p_revision THEN RETURN jsonb_build_object('conflict',true); END IF;
 IF p_kind='answer' AND (target.status<>'active' OR clock_timestamp()>=target.expires_at)
 THEN RAISE EXCEPTION 'simulation_time_expired' USING ERRCODE='55000'; END IF;
 IF p_kind='review' AND target.status<>'completed' THEN RAISE EXCEPTION 'simulation_not_completed' USING ERRCODE='23514'; END IF;
 IF p_kind NOT IN('answer','finish','review') THEN RAISE EXCEPTION 'invalid_simulation_change' USING ERRCODE='23514'; END IF;
 IF (p_kind='answer' AND p_snapshot->>'status' IS DISTINCT FROM 'active')
 OR (p_kind IN('finish','review') AND p_snapshot->>'status' IS DISTINCT FROM 'completed')
 OR (p_kind='finish' AND p_snapshot->'answers' IS DISTINCT FROM target.server_snapshot->'answers')
 THEN RAISE EXCEPTION 'invalid_simulation_transition' USING ERRCODE='23514'; END IF;
 UPDATE public.sitov_simulation_runs SET server_snapshot=p_snapshot,status=p_snapshot->>'status',
  completed_at=(p_snapshot->>'completedAt')::timestamptz,revision=revision+1 WHERE id=p_run_id RETURNING * INTO target;
 INSERT INTO public.sitov_simulation_receipts(student_id,request_id,run_id,kind,payload_hash) VALUES(p_student_id,p_request_id,p_run_id,p_kind,p_payload_hash);
 RETURN jsonb_build_object('snapshot',target.server_snapshot,'revision',target.revision,'replayed',false);
END $$;
REVOKE ALL ON FUNCTION public.sitov_store_simulation_change(uuid,uuid,integer,jsonb,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_store_simulation_change(uuid,uuid,integer,jsonb,uuid,text,text) TO service_role;
NOTIFY pgrst,'reload schema';
-- END SITOV SIMULATION FEATURE ACCESS

-- BEGIN SITOV SIMULATION STAFF RESET
-- Sitov Academy: only assigned staff may erase simulation progress.
-- A durable job fences old pages and signed uploads before private file cleanup.
CREATE TABLE IF NOT EXISTS sitov_simulation_private.reset_jobs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 generation bigint NOT NULL CHECK(generation>0),
 requested_by uuid NOT NULL,
 status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','completed')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), completed_at timestamptz,
 UNIQUE(id,student_id), UNIQUE(student_id,generation),
 CHECK((status='pending' AND completed_at IS NULL) OR (status='completed' AND completed_at IS NOT NULL))
);
CREATE TABLE IF NOT EXISTS sitov_simulation_private.reset_media (
 job_id uuid NOT NULL REFERENCES sitov_simulation_private.reset_jobs(id) ON DELETE CASCADE,
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 bucket text NOT NULL CHECK(bucket='sitov-exam-submissions'),
 path text NOT NULL CHECK(length(path)<=300 AND strpos(path,'..')=0 AND path LIKE student_id::text||'/speaking/%'),
 PRIMARY KEY(job_id,path),
 FOREIGN KEY(job_id,student_id) REFERENCES sitov_simulation_private.reset_jobs(id,student_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS sitov_simulation_reset_media_path_idx ON sitov_simulation_private.reset_media(path);
CREATE TABLE IF NOT EXISTS sitov_simulation_private.reset_requests (
 student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 request_id uuid NOT NULL, job_id uuid NOT NULL,
 requested_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(student_id,request_id),
 FOREIGN KEY(job_id,student_id) REFERENCES sitov_simulation_private.reset_jobs(id,student_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS public.sitov_simulation_learning_state (
 student_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),
 reset_pending uuid REFERENCES sitov_simulation_private.reset_jobs(id) ON DELETE SET NULL
);
ALTER TABLE public.sitov_simulation_runs ADD COLUMN IF NOT EXISTS generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0);
ALTER TABLE public.sitov_simulation_learning_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sitov_simulation_learning_state FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.sitov_simulation_learning_state TO service_role;
DO $$ DECLARE name text; BEGIN
 FOREACH name IN ARRAY ARRAY['reset_jobs','reset_media','reset_requests'] LOOP
  EXECUTE format('ALTER TABLE sitov_simulation_private.%I ENABLE ROW LEVEL SECURITY',name);
  EXECUTE format('REVOKE ALL ON sitov_simulation_private.%I FROM PUBLIC,anon,authenticated',name);
  EXECUTE format('GRANT ALL ON sitov_simulation_private.%I TO service_role',name);
 END LOOP;
END $$;

-- Always obtain current authorization after the shared learner lock.
ALTER FUNCTION sitov_simulation_private.feature_allowed(uuid) VOLATILE;
CREATE OR REPLACE FUNCTION sitov_simulation_private.assert_reset_staff(p_student uuid,p_staff uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_student AND role='student')
 OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=p_staff AND (p.role='admin' OR (p.role='teacher' AND EXISTS(
  SELECT 1 FROM public.sitov_exam_teacher_assignments a WHERE a.student_id=p_student AND a.teacher_id=p_staff))))
 THEN RAISE EXCEPTION 'unauthorized_simulation_reset' USING ERRCODE='42501'; END IF;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.assert_reset_staff(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION sitov_simulation_private.assert_reset_staff(uuid,uuid) TO service_role;

-- Existing learning-reset internals stay private; this helper exposes no rows.
CREATE OR REPLACE FUNCTION sitov_simulation_private.assert_no_global_reset(p_student uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM learning_reset_private.jobs WHERE auth_user_id=p_student AND
  (active OR completed_at>transaction_timestamp()))
 THEN RAISE EXCEPTION 'learning_reset_in_progress' USING ERRCODE='55000'; END IF;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.assert_no_global_reset(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION sitov_simulation_private.assert_no_global_reset(uuid) TO service_role;

CREATE OR REPLACE FUNCTION sitov_simulation_private.lock_assignment() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||CASE WHEN TG_OP='DELETE' THEN OLD.student_id ELSE NEW.student_id END::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.lock_assignment() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_assignment_lock ON public.sitov_exam_teacher_assignments;
CREATE TRIGGER sitov_simulation_assignment_lock BEFORE INSERT OR UPDATE OR DELETE ON public.sitov_exam_teacher_assignments FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.lock_assignment();

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_reset_run() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE current_generation bigint; pending uuid; BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 SELECT generation,reset_pending INTO current_generation,pending FROM public.sitov_simulation_learning_state WHERE student_id=NEW.student_id;
 IF pending IS NOT NULL THEN RAISE EXCEPTION 'simulation_reset_in_progress' USING ERRCODE='55000'; END IF;
 IF NEW.generation<>coalesce(current_generation,0) THEN RAISE EXCEPTION 'simulation_generation_changed' USING ERRCODE='55000'; END IF;
 IF TG_OP='UPDATE' AND NEW.generation<>OLD.generation THEN RAISE EXCEPTION 'immutable_simulation_assignment' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_reset_run() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_reset_epoch_guard ON public.sitov_simulation_runs;
CREATE TRIGGER sitov_simulation_reset_epoch_guard BEFORE INSERT OR UPDATE ON public.sitov_simulation_runs FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_reset_run();

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_retired_ticket() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 IF EXISTS(SELECT 1 FROM sitov_simulation_private.reset_media WHERE path=NEW.path)
 THEN RAISE EXCEPTION 'simulation_recording_retired' USING ERRCODE='55000'; END IF;
 IF NEW.simulation_run_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.sitov_simulation_learning_state WHERE student_id=NEW.student_id AND reset_pending IS NOT NULL)
 THEN RAISE EXCEPTION 'simulation_reset_in_progress' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_retired_ticket() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_retired_ticket_guard ON public.sitov_exam_upload_tickets;
CREATE TRIGGER sitov_simulation_retired_ticket_guard BEFORE INSERT OR UPDATE ON public.sitov_exam_upload_tickets FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_retired_ticket();

CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_retired_storage() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE learner uuid; BEGIN
 IF NEW.bucket_id<>'sitov-exam-submissions' THEN RETURN NEW; END IF;
 SELECT student_id INTO learner FROM public.sitov_exam_upload_tickets WHERE path=NEW.name;
 IF learner IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||learner::text,0)); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 IF EXISTS(SELECT 1 FROM sitov_simulation_private.reset_media WHERE path=NEW.name)
 THEN RAISE EXCEPTION 'simulation_recording_retired' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_retired_storage() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_retired_storage_guard ON storage.objects;
CREATE TRIGGER sitov_simulation_retired_storage_guard BEFORE INSERT OR UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_retired_storage();

-- A preparation edit may not acquire a file after staff queued its deletion.
CREATE OR REPLACE FUNCTION sitov_simulation_private.guard_retired_preparation_media() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||NEW.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 IF EXISTS(SELECT 1 FROM sitov_simulation_private.reset_media WHERE path=NEW.media_path OR path=NEW.photo_path)
 THEN RAISE EXCEPTION 'simulation_recording_retired' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_simulation_private.guard_retired_preparation_media() FROM PUBLIC,anon,authenticated,service_role;
DROP TRIGGER IF EXISTS sitov_simulation_preparation_media_guard ON public.sitov_exam_submissions;
CREATE TRIGGER sitov_simulation_preparation_media_guard BEFORE INSERT OR UPDATE ON public.sitov_exam_submissions FOR EACH ROW EXECUTE FUNCTION sitov_simulation_private.guard_retired_preparation_media();

CREATE OR REPLACE FUNCTION public.sitov_begin_simulation_reset(p_student_id uuid,p_staff_id uuid,p_request_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE state public.sitov_simulation_learning_state; job sitov_simulation_private.reset_jobs; receipt sitov_simulation_private.reset_requests; media jsonb; BEGIN
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'simulation_reset_request_required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||p_student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 PERFORM sitov_simulation_private.assert_reset_staff(p_student_id,p_staff_id);
 PERFORM sitov_simulation_private.assert_no_global_reset(p_student_id);
 SELECT * INTO receipt FROM sitov_simulation_private.reset_requests WHERE student_id=p_student_id AND request_id=p_request_id;
 IF FOUND THEN
  IF receipt.requested_by<>p_staff_id THEN RAISE EXCEPTION 'simulation_reset_request_reused' USING ERRCODE='23514'; END IF;
  SELECT * INTO job FROM sitov_simulation_private.reset_jobs WHERE id=receipt.job_id;
 ELSE
  INSERT INTO public.sitov_simulation_learning_state(student_id) VALUES(p_student_id) ON CONFLICT DO NOTHING;
  SELECT * INTO state FROM public.sitov_simulation_learning_state WHERE student_id=p_student_id FOR UPDATE;
  IF state.reset_pending IS NOT NULL THEN
   SELECT * INTO job FROM sitov_simulation_private.reset_jobs WHERE id=state.reset_pending;
  ELSE
   INSERT INTO sitov_simulation_private.reset_jobs(student_id,generation,requested_by) VALUES(p_student_id,state.generation+1,p_staff_id) RETURNING * INTO job;
   UPDATE public.sitov_simulation_learning_state SET generation=job.generation,reset_pending=job.id WHERE student_id=p_student_id;
   -- Capture before deleting snapshots/tickets, including unused uploaded files.
   -- A real preparation submission keeps its shared recording and upload ticket.
   INSERT INTO sitov_simulation_private.reset_media(job_id,student_id,bucket,path)
   SELECT job.id,p_student_id,'sitov-exam-submissions',candidate.path FROM (
    SELECT t.path FROM public.sitov_exam_upload_tickets t WHERE t.student_id=p_student_id AND t.simulation_run_id IS NOT NULL
    UNION
    SELECT a.value->>'audioPath' FROM public.sitov_simulation_runs r
     CROSS JOIN LATERAL jsonb_each(r.server_snapshot->'answers') a WHERE r.student_id=p_student_id AND jsonb_typeof(a.value)='object'
   ) candidate WHERE candidate.path LIKE p_student_id::text||'/speaking/%' AND length(candidate.path)<=300 AND strpos(candidate.path,'..')=0
    AND NOT EXISTS(SELECT 1 FROM public.sitov_exam_submissions s WHERE s.media_path=candidate.path OR s.photo_path=candidate.path);
   -- Convert shared preparation references to their original independent ticket.
   -- Otherwise the run FK cascade would silently remove their upload ownership.
   UPDATE public.sitov_exam_upload_tickets t SET simulation_run_id=NULL
    WHERE t.student_id=p_student_id AND t.simulation_run_id IS NOT NULL
     AND EXISTS(SELECT 1 FROM public.sitov_exam_submissions s WHERE s.media_path=t.path OR s.photo_path=t.path);
   DELETE FROM public.sitov_exam_upload_tickets t WHERE t.student_id=p_student_id AND EXISTS(
    SELECT 1 FROM sitov_simulation_private.reset_media m WHERE m.job_id=job.id AND m.path=t.path);
   DELETE FROM public.sitov_simulation_runs WHERE student_id=p_student_id;
  END IF;
  INSERT INTO sitov_simulation_private.reset_requests(student_id,request_id,job_id,requested_by) VALUES(p_student_id,p_request_id,job.id,p_staff_id);
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('bucket',m.bucket,'path',m.path) ORDER BY m.path),'[]'::jsonb) INTO media
  FROM sitov_simulation_private.reset_media m JOIN storage.objects o ON o.bucket_id=m.bucket AND o.name=m.path
  WHERE m.job_id=job.id AND job.status='pending';
 RETURN jsonb_build_object('jobId',job.id,'status',job.status,'generation',job.generation,'media',media);
END $$;
CREATE OR REPLACE FUNCTION public.sitov_finish_simulation_reset(p_job_id uuid,p_staff_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE job sitov_simulation_private.reset_jobs; BEGIN
 SELECT * INTO job FROM sitov_simulation_private.reset_jobs WHERE id=p_job_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'simulation_reset_not_found' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||job.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 PERFORM sitov_simulation_private.assert_reset_staff(job.student_id,p_staff_id);
 SELECT * INTO job FROM sitov_simulation_private.reset_jobs WHERE id=p_job_id FOR UPDATE;
 IF job.status='completed' THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM sitov_simulation_private.reset_media m JOIN storage.objects o ON o.bucket_id=m.bucket AND o.name=m.path WHERE m.job_id=job.id)
 THEN RAISE EXCEPTION 'simulation_audio_removal_incomplete' USING ERRCODE='55000'; END IF;
 UPDATE public.sitov_simulation_learning_state SET reset_pending=NULL WHERE student_id=job.student_id AND reset_pending=job.id AND generation=job.generation;
 IF NOT FOUND THEN RAISE EXCEPTION 'simulation_reset_generation_changed' USING ERRCODE='55000'; END IF;
 UPDATE sitov_simulation_private.reset_jobs SET status='completed',completed_at=clock_timestamp() WHERE id=job.id;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.sitov_begin_simulation_reset(uuid,uuid,uuid),public.sitov_finish_simulation_reset(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_begin_simulation_reset(uuid,uuid,uuid),public.sitov_finish_simulation_reset(uuid,uuid) TO service_role;

-- General learner reset deliberately preserves all simulation evidence.
-- NULL preparation tickets reused in a frozen simulation count as evidence too.
CREATE OR REPLACE FUNCTION sitov_simulation_private.preserve_media(p_student uuid,p_path text) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.sitov_exam_upload_tickets t WHERE t.student_id=p_student AND t.path=p_path AND t.simulation_run_id IS NOT NULL)
 OR EXISTS(SELECT 1 FROM public.sitov_simulation_runs r CROSS JOIN LATERAL jsonb_each(r.server_snapshot->'answers') a
  WHERE r.student_id=p_student AND jsonb_typeof(a.value)='object' AND a.value->>'audioPath'=p_path)
 OR EXISTS(SELECT 1 FROM sitov_simulation_private.reset_media m JOIN sitov_simulation_private.reset_jobs j ON j.id=m.job_id
  WHERE m.student_id=p_student AND m.path=p_path AND j.status='pending')
$$;
REVOKE ALL ON FUNCTION sitov_simulation_private.preserve_media(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION sitov_exam_private.capture_reset_media(p_student uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF auth.uid() IS NULL OR p_student IS DISTINCT FROM auth.uid() OR NOT EXISTS(
 SELECT 1 FROM learning_reset_private.jobs WHERE auth_user_id=p_student AND active)
 THEN RAISE EXCEPTION 'reset_owner_required' USING ERRCODE='42501'; END IF;
 DELETE FROM learning_reset_private.audio_objects a WHERE a.auth_user_id=p_student AND a.bucket_id='sitov-exam-submissions'
  AND sitov_simulation_private.preserve_media(p_student,a.object_name);
 INSERT INTO learning_reset_private.audio_objects(auth_user_id,object_id,bucket_id,object_name)
 SELECT p_student,o.id,o.bucket_id,o.name FROM storage.objects o
 WHERE o.bucket_id='sitov-exam-submissions' AND split_part(o.name,'/',1)=p_student::text
 AND NOT sitov_simulation_private.preserve_media(p_student,o.name)
 AND NOT EXISTS(SELECT 1 FROM learning_reset_private.audio_objects a WHERE a.auth_user_id=p_student AND a.object_id=o.id);
END $$;
-- Also protect simulations captured by an unfinished reset before this upgrade.
DELETE FROM learning_reset_private.audio_objects a WHERE a.bucket_id='sitov-exam-submissions'
 AND sitov_simulation_private.preserve_media(a.auth_user_id,a.object_name);
CREATE OR REPLACE FUNCTION learning_reset_private.can_remove_audio(p_id uuid) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS(
 SELECT 1 FROM learning_reset_private.audio_objects a JOIN learning_reset_private.jobs j USING(auth_user_id)
 WHERE a.auth_user_id=(SELECT auth.uid()) AND a.object_id=p_id AND j.active
  AND (a.bucket_id<>'sitov-exam-submissions' OR NOT sitov_simulation_private.preserve_media(a.auth_user_id,a.object_name)))
$$;
CREATE OR REPLACE FUNCTION learning_reset_private.audio_batch(p_token uuid) RETURNS TABLE(bucket_id text,object_name text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=(SELECT auth.uid()); BEGIN
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM learning_reset_private.jobs WHERE auth_user_id=actor AND token=p_token)
 THEN RAISE EXCEPTION 'reset_owner_required' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT a.bucket_id,a.object_name FROM learning_reset_private.audio_objects a
  JOIN storage.objects o ON o.id=a.object_id AND o.bucket_id=a.bucket_id AND o.name=a.object_name
  JOIN learning_reset_private.jobs j ON j.auth_user_id=a.auth_user_id
  WHERE a.auth_user_id=actor AND j.active
   AND (a.bucket_id<>'sitov-exam-submissions' OR NOT sitov_simulation_private.preserve_media(actor,a.object_name))
  ORDER BY a.bucket_id,a.object_name LIMIT 500;
END $$;
CREATE OR REPLACE FUNCTION sitov_exam_private.guard_storage_upload() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE learner uuid; issued timestamptz; BEGIN
 IF NEW.bucket_id<>'sitov-exam-submissions' THEN RETURN NEW; END IF;
 SELECT t.student_id,t.created_at INTO learner,issued FROM public.sitov_exam_upload_tickets t JOIN public.profiles p ON p.id=t.student_id WHERE t.path=NEW.name;
 IF learner IS NULL THEN RAISE EXCEPTION 'exam_upload_ticket_expired' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||learner::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 PERFORM learning_reset_private.assert_writable(learner);
 IF NOT EXISTS(SELECT 1 FROM public.sitov_exam_upload_tickets WHERE path=NEW.name)
 OR (EXISTS(SELECT 1 FROM learning_reset_private.jobs WHERE auth_user_id=learner AND completed_at>=issued)
  AND NOT sitov_simulation_private.preserve_media(learner,NEW.name))
 THEN RAISE EXCEPTION 'exam_upload_ticket_expired' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
DO $sitov$ DECLARE body text; previous text; replacement text; BEGIN
 body:=pg_get_functiondef('learning_reset_private.finish_reset(uuid)'::regprocedure);
 IF strpos(body,'sitov-simulation-preserve-queued-media')=0 THEN
  previous:='IF NOT job.active THEN RETURN true; END IF;';
  IF strpos(body,previous)=0 THEN RAISE EXCEPTION 'sitov_simulation_global_reset_queue_contract_changed'; END IF;
  body:=replace(body,previous,previous||$fragment$
 -- sitov-simulation-preserve-queued-media: an old token cannot acquire simulation evidence.
 DELETE FROM learning_reset_private.audio_objects a WHERE a.auth_user_id=actor AND a.bucket_id='sitov-exam-submissions'
  AND sitov_simulation_private.preserve_media(actor,a.object_name);$fragment$);
 END IF;
 previous:='DELETE FROM public.sitov_simulation_runs WHERE student_id=actor;';
 IF strpos(body,previous)>0 THEN body:=replace(body,previous,'-- Simulation history is reset only by assigned staff.'); END IF;
 previous:='DELETE FROM public.sitov_exam_upload_tickets WHERE student_id=actor;';
 replacement:='DELETE FROM public.sitov_exam_upload_tickets WHERE student_id=actor AND NOT sitov_simulation_private.preserve_media(actor,path);';
 IF strpos(body,replacement)=0 THEN
  IF strpos(body,previous)=0 THEN RAISE EXCEPTION 'sitov_simulation_global_reset_contract_changed'; END IF;
  body:=replace(body,previous,replacement);
 END IF;
 EXECUTE body;
END $sitov$;
REVOKE ALL ON FUNCTION sitov_exam_private.capture_reset_media(uuid),sitov_exam_private.guard_storage_upload() FROM PUBLIC,anon,authenticated,service_role;
-- Account deletion retains its existing broad private-file manifest and FK cascades.
NOTIFY pgrst,'reload schema';
-- END SITOV SIMULATION STAFF RESET

-- BEGIN SITOV SIMULATION TEACHER MANAGEMENT
-- Sitov Academy: teachers can take responsibility for an unassigned learner.
-- Existing assignments remain exclusive; administrators retain reassignment.
CREATE OR REPLACE FUNCTION sitov_exam_private.validate_assignment() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 -- UPDATE may already hold the assignment row lock. Keep advisory locking
 -- in the claim RPC before it touches that row, avoiding the reverse order.
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.student_id AND role='student')
 OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.teacher_id AND role IN('teacher','admin'))
 OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.assigned_by AND (
  p.role='admin' OR (p.role='teacher' AND p.id=NEW.teacher_id
   AND (TG_OP='INSERT' OR (OLD.teacher_id=NEW.teacher_id AND OLD.student_id=NEW.student_id)))))
 THEN RAISE EXCEPTION 'invalid_exam_teacher_assignment' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_exam_private.validate_assignment() FROM PUBLIC,anon,authenticated,service_role;

-- Only trusted server code supplies the authenticated staff ID. The invoker
-- must hold service_role's existing table privileges; this function adds none.
CREATE OR REPLACE FUNCTION public.sitov_assign_simulation_student(p_student_id uuid,p_staff_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE assigned_teacher uuid; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_staff_id AND role IN('teacher','admin'))
 THEN RAISE EXCEPTION 'unauthorized_simulation_assignment' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||p_student_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_student_id AND role='student')
 THEN RAISE EXCEPTION 'invalid_simulation_student' USING ERRCODE='42501'; END IF;

 INSERT INTO public.sitov_exam_teacher_assignments(student_id,teacher_id,assigned_by,response_days)
 VALUES(p_student_id,p_staff_id,p_staff_id,7) ON CONFLICT(student_id) DO NOTHING;
 SELECT teacher_id INTO assigned_teacher FROM public.sitov_exam_teacher_assignments
 WHERE student_id=p_student_id FOR UPDATE;
 IF assigned_teacher IS DISTINCT FROM p_staff_id
 THEN RAISE EXCEPTION 'simulation_student_already_assigned' USING ERRCODE='42501'; END IF;

 INSERT INTO public.sitov_simulation_feature_grants(student_id,granted_by)
 VALUES(p_student_id,p_staff_id) ON CONFLICT(student_id) DO NOTHING;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.sitov_assign_simulation_student(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_assign_simulation_student(uuid,uuid) TO service_role;
-- END SITOV SIMULATION TEACHER MANAGEMENT

-- BEGIN SITOV STORAGE SECURITY LIMITS
-- Sitov Academy: atomic quotas cover Storage API writes, including service_role,
-- signed uploads, TUS final metadata and INSERT ... ON CONFLICT replacements.
-- Keep existing objects, paths, learning records and prepared German audio intact.
CREATE SCHEMA IF NOT EXISTS sitov_storage_private;
REVOKE ALL ON SCHEMA sitov_storage_private FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA sitov_storage_private TO service_role;
CREATE TABLE IF NOT EXISTS sitov_storage_private.limits (
 bucket_id text PRIMARY KEY, file_bytes bigint NOT NULL, bucket_bytes bigint NOT NULL,
 bucket_objects bigint NOT NULL, user_bytes bigint, user_objects bigint,
 daily_objects bigint, daily_bytes bigint
);
INSERT INTO sitov_storage_private.limits VALUES
 ('pronunciation_audio',26214400,5368709120,20000,262144000,200,25,536870912),
 ('sitov-exam-submissions',20971520,10737418240,40000,524288000,400,40,629145600),
 ('audio_cache',2097152,8589934592,100000,NULL,NULL,NULL,NULL),
 ('course-assets',536870912,32212254720,20000,NULL,NULL,NULL,NULL)
ON CONFLICT(bucket_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS sitov_storage_private.usage (
 scope text PRIMARY KEY, bytes bigint NOT NULL DEFAULT 0 CHECK(bytes>=0),
 objects bigint NOT NULL DEFAULT 0 CHECK(objects>=0)
);
CREATE TABLE IF NOT EXISTS sitov_storage_private.daily (
 day date NOT NULL, scope text NOT NULL, objects bigint NOT NULL DEFAULT 0 CHECK(objects>=0),
 bytes bigint NOT NULL DEFAULT 0 CHECK(bytes>=0), PRIMARY KEY(day,scope)
);
ALTER TABLE sitov_storage_private.limits ENABLE ROW LEVEL SECURITY;
ALTER TABLE sitov_storage_private.usage ENABLE ROW LEVEL SECURITY;
ALTER TABLE sitov_storage_private.daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA sitov_storage_private FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA sitov_storage_private TO service_role;

-- Storage initially inserts a row without final size for some upload protocols.
-- Reserve the full file maximum until the Storage service writes measured size.
-- user_metadata is deliberately never used as a trusted source of size/owner.
CREATE OR REPLACE FUNCTION sitov_storage_private.object_bytes(p_metadata jsonb,p_max bigint)
RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE value text; BEGIN
 value:=p_metadata->>'size';
 IF value IS NULL THEN RETURN p_max; END IF;
 IF value !~ '^[0-9]{1,18}$' THEN RAISE EXCEPTION 'sitov_invalid_storage_size' USING ERRCODE='23514'; END IF;
 RETURN value::bigint;
END $$;

-- Do not recalculate counters when reapplying: daily usage must survive deletes
-- and resets. The deployment runner executes this migration once under its lock.
LOCK TABLE storage.objects IN SHARE ROW EXCLUSIVE MODE;
WITH objects AS (
 SELECT o.bucket_id,split_part(o.name,'/',1) owner,
 sitov_storage_private.object_bytes(o.metadata,l.file_bytes) bytes
 FROM storage.objects o JOIN sitov_storage_private.limits l USING(bucket_id)
), scopes AS (
 SELECT 'all' scope,bytes FROM objects
 UNION ALL SELECT 'protected-audio',bytes FROM objects WHERE bucket_id<>'course-assets'
 UNION ALL SELECT 'bucket:'||bucket_id,bytes FROM objects
 UNION ALL SELECT 'user:'||owner,bytes FROM objects WHERE bucket_id IN('pronunciation_audio','sitov-exam-submissions')
 UNION ALL SELECT 'user-bucket:'||bucket_id||':'||owner,bytes FROM objects WHERE bucket_id IN('pronunciation_audio','sitov-exam-submissions')
)
INSERT INTO sitov_storage_private.usage(scope,bytes,objects)
SELECT scope,sum(bytes),count(*) FROM scopes GROUP BY scope ON CONFLICT(scope) DO NOTHING;

-- UPDATE locks the current counter tuple and re-evaluates the bound after any
-- concurrent writer commits. SUM + advisory locking on a caller snapshot is not
-- the quota primitive. A failure rolls back all counters and the Storage write.
CREATE OR REPLACE FUNCTION sitov_storage_private.charge(p_scope text,p_bytes bigint,p_objects bigint,p_max_bytes bigint,p_max_objects bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 INSERT INTO sitov_storage_private.usage(scope) VALUES(p_scope) ON CONFLICT DO NOTHING;
 UPDATE sitov_storage_private.usage SET bytes=bytes+p_bytes,objects=objects+p_objects
 WHERE scope=p_scope AND bytes+p_bytes>=0 AND objects+p_objects>=0 AND (
  (p_bytes<=0 AND p_objects<=0) OR
  ((p_max_bytes IS NULL OR bytes+p_bytes<=p_max_bytes) AND (p_max_objects IS NULL OR objects+p_objects<=p_max_objects))
 );
 IF NOT FOUND THEN RAISE EXCEPTION 'sitov_storage_quota_exceeded' USING ERRCODE='PT413'; END IF;
END $$;
CREATE OR REPLACE FUNCTION sitov_storage_private.charge_daily(p_scope text,p_objects bigint,p_bytes bigint,p_max_objects bigint,p_max_bytes bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE sitov_day date:=(clock_timestamp() AT TIME ZONE 'UTC')::date; BEGIN
 INSERT INTO sitov_storage_private.daily(day,scope) VALUES(sitov_day,p_scope) ON CONFLICT DO NOTHING;
 UPDATE sitov_storage_private.daily SET objects=objects+p_objects,bytes=bytes+p_bytes
 WHERE day=sitov_day AND scope=p_scope
 AND objects+p_objects<=p_max_objects AND bytes+p_bytes<=p_max_bytes;
 IF NOT FOUND THEN RAISE EXCEPTION 'sitov_daily_upload_limit' USING ERRCODE='PT429'; END IF;
END $$;
CREATE OR REPLACE FUNCTION sitov_storage_private.enforce_quota() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE bounds sitov_storage_private.limits; bucket text; owner text;
 new_bytes bigint:=0; old_bytes bigint:=0; byte_delta bigint; object_delta bigint:=0; BEGIN
 IF TG_OP='DELETE' THEN bucket:=OLD.bucket_id; owner:=split_part(OLD.name,'/',1);
 ELSE bucket:=NEW.bucket_id; owner:=split_part(NEW.name,'/',1); END IF;
 -- Moving into/out of a protected bucket must not bypass its ledger. Storage
 -- uploads use immutable names; a legitimate copy gets its own INSERT charge.
 IF TG_OP='UPDATE' AND ROW(NEW.bucket_id,NEW.name) IS DISTINCT FROM ROW(OLD.bucket_id,OLD.name)
 AND (EXISTS(SELECT 1 FROM sitov_storage_private.limits WHERE bucket_id=OLD.bucket_id)
 OR EXISTS(SELECT 1 FROM sitov_storage_private.limits WHERE bucket_id=NEW.bucket_id))
 THEN RAISE EXCEPTION 'sitov_storage_path_is_immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO bounds FROM sitov_storage_private.limits WHERE bucket_id=bucket;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF TG_OP<>'DELETE' AND bucket IN('pronunciation_audio','sitov-exam-submissions') AND owner !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
 THEN RAISE EXCEPTION 'sitov_invalid_storage_owner' USING ERRCODE='23514'; END IF;
 IF TG_OP<>'DELETE' THEN
  new_bytes:=sitov_storage_private.object_bytes(NEW.metadata,bounds.file_bytes);
  IF new_bytes>bounds.file_bytes THEN RAISE EXCEPTION 'sitov_storage_file_too_large' USING ERRCODE='PT413'; END IF;
 END IF;
 IF TG_OP<>'INSERT' THEN old_bytes:=sitov_storage_private.object_bytes(OLD.metadata,bounds.file_bytes); END IF;
 byte_delta:=new_bytes-old_bytes;
 IF TG_OP='INSERT' THEN object_delta:=1; ELSIF TG_OP='DELETE' THEN object_delta:=-1; END IF;
 -- Every writer takes the combined counter first: deterministic lock order.
 PERFORM sitov_storage_private.charge('all',byte_delta,object_delta,53687091200,180000);
 IF bucket<>'course-assets' THEN PERFORM sitov_storage_private.charge('protected-audio',byte_delta,object_delta,21474836480,160000); END IF;
 PERFORM sitov_storage_private.charge('bucket:'||bucket,byte_delta,object_delta,bounds.bucket_bytes,bounds.bucket_objects);
 IF bucket IN('pronunciation_audio','sitov-exam-submissions') THEN
  PERFORM sitov_storage_private.charge('user:'||owner,byte_delta,object_delta,786432000,600);
  PERFORM sitov_storage_private.charge('user-bucket:'||bucket||':'||owner,byte_delta,object_delta,bounds.user_bytes,bounds.user_objects);
  IF TG_OP='INSERT' OR byte_delta>0 THEN
   PERFORM sitov_storage_private.charge_daily('uploads:'||bucket||':'||owner,greatest(object_delta,0),greatest(byte_delta,0),bounds.daily_objects,bounds.daily_bytes);
  END IF;
 END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS sitov_storage_security_quota ON storage.objects;
CREATE TRIGGER sitov_storage_security_quota AFTER INSERT OR UPDATE OR DELETE ON storage.objects
FOR EACH ROW EXECUTE FUNCTION sitov_storage_private.enforce_quota();

ALTER TABLE public.sitov_exam_upload_tickets ADD COLUMN IF NOT EXISTS expires_at timestamptz;
ALTER TABLE public.sitov_exam_upload_tickets ADD COLUMN IF NOT EXISTS expected_bytes bigint;
-- Existing tickets retain valid lifetime; their stored files remain accessible.
-- Historical tickets can refer to completed/retired runs. Backfilling only a
-- deadline must not replay business write validation for those historical rows.
-- The runner owns one transaction: block all ticket writers, retain every
-- original trigger mode, disable only user triggers, then restore exact modes.
LOCK TABLE public.sitov_exam_upload_tickets IN ACCESS EXCLUSIVE MODE;
DO $$ DECLARE sitov_triggers text[]; sitov_modes "char"[]; sitov_index integer; BEGIN
 SELECT array_agg(tgname ORDER BY tgname),array_agg(tgenabled ORDER BY tgname)
 INTO sitov_triggers,sitov_modes FROM pg_trigger
 WHERE tgrelid='public.sitov_exam_upload_tickets'::regclass AND NOT tgisinternal AND tgenabled<>'D';
 IF sitov_triggers IS NOT NULL THEN
  FOR sitov_index IN 1..array_length(sitov_triggers,1) LOOP
   EXECUTE format('ALTER TABLE public.sitov_exam_upload_tickets DISABLE TRIGGER %I',sitov_triggers[sitov_index]);
  END LOOP;
 END IF;
 UPDATE public.sitov_exam_upload_tickets SET expires_at=created_at+interval '30 minutes' WHERE expires_at IS NULL;
 IF sitov_triggers IS NOT NULL THEN
  FOR sitov_index IN 1..array_length(sitov_triggers,1) LOOP
   EXECUTE format('ALTER TABLE public.sitov_exam_upload_tickets %s TRIGGER %I',
    CASE sitov_modes[sitov_index] WHEN 'A' THEN 'ENABLE ALWAYS' WHEN 'R' THEN 'ENABLE REPLICA' ELSE 'ENABLE' END,sitov_triggers[sitov_index]);
  END LOOP;
 END IF;
END $$;
ALTER TABLE public.sitov_exam_upload_tickets ALTER COLUMN expires_at SET DEFAULT (clock_timestamp()+interval '30 minutes');
ALTER TABLE public.sitov_exam_upload_tickets ALTER COLUMN expires_at SET NOT NULL;
CREATE INDEX IF NOT EXISTS sitov_exam_ticket_expiry ON public.sitov_exam_upload_tickets(student_id,expires_at);
CREATE OR REPLACE FUNCTION sitov_storage_private.guard_exam_ticket() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.path,NEW.student_id,NEW.kind,NEW.created_at,NEW.expires_at,NEW.expected_bytes)
  IS DISTINCT FROM ROW(OLD.path,OLD.student_id,OLD.kind,OLD.created_at,OLD.expires_at,OLD.expected_bytes)
  THEN RAISE EXCEPTION 'sitov_upload_ticket_is_immutable' USING ERRCODE='23514'; END IF;
  IF NEW.simulation_run_id IS DISTINCT FROM OLD.simulation_run_id THEN
   -- The service-only staff reset must detach a recording also used by the
   -- same learner's preparation submission before deleting its simulation FK.
   -- Preserve the exact owner, path, lifetime and byte bound; no generic
   -- service-role exemption and no caller-settable reset flag authorizes this.
   IF OLD.simulation_run_id IS NULL OR NEW.simulation_run_id IS NOT NULL
   OR coalesce(nullif(current_setting('role',true),'none'),session_user)<>'service_role'
   OR NOT EXISTS(
    SELECT 1 FROM public.sitov_simulation_learning_state s
    JOIN sitov_simulation_private.reset_jobs j ON j.id=s.reset_pending AND j.student_id=s.student_id
    JOIN public.sitov_simulation_runs r ON r.id=OLD.simulation_run_id AND r.student_id=s.student_id
    WHERE s.student_id=OLD.student_id AND j.status='pending' AND j.generation=s.generation)
   OR NOT EXISTS(SELECT 1 FROM public.sitov_exam_submissions s
    WHERE s.student_id=OLD.student_id AND (s.media_path=OLD.path OR s.photo_path=OLD.path))
   THEN RAISE EXCEPTION 'sitov_upload_ticket_is_immutable' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.expires_at>clock_timestamp()+interval '30 minutes' OR NEW.expires_at<=clock_timestamp()
 OR NEW.expected_bytes IS NULL OR NEW.expected_bytes NOT BETWEEN 1 AND 20971520
 THEN RAISE EXCEPTION 'sitov_invalid_upload_ticket' USING ERRCODE='23514'; END IF;
 -- Issuance itself consumes quota, even if its URL is never used or deleted.
 PERFORM sitov_storage_private.charge_daily('tickets:'||NEW.student_id::text,1,NEW.expected_bytes,40,629145600);
 -- Discard stale unused authorizations, never Storage files or used tickets.
 DELETE FROM public.sitov_exam_upload_tickets t WHERE t.student_id=NEW.student_id AND t.expires_at<=clock_timestamp()
 AND NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='sitov-exam-submissions' AND o.name=t.path);
 IF (SELECT count(*) FROM public.sitov_exam_upload_tickets t
  WHERE t.student_id=NEW.student_id AND t.expires_at>clock_timestamp()
  AND NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='sitov-exam-submissions' AND o.name=t.path))>=10
 THEN RAISE EXCEPTION 'sitov_pending_upload_limit' USING ERRCODE='PT429'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sitov_upload_ticket_limit ON public.sitov_exam_upload_tickets;
CREATE TRIGGER sitov_upload_ticket_limit BEFORE INSERT OR UPDATE ON public.sitov_exam_upload_tickets
FOR EACH ROW EXECUTE FUNCTION sitov_storage_private.guard_exam_ticket();

-- Keep the reset fencing and lock order from 73; check the immutable ticket
-- again after waiting, and enforce expiry/size on creation and finalization.
CREATE OR REPLACE FUNCTION sitov_exam_private.guard_storage_upload() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE ticket public.sitov_exam_upload_tickets; needs_ticket boolean; BEGIN
 IF NEW.bucket_id<>'sitov-exam-submissions' THEN RETURN NEW; END IF;
 SELECT * INTO ticket FROM public.sitov_exam_upload_tickets WHERE path=NEW.name;
 IF ticket.student_id IS NULL THEN RAISE EXCEPTION 'exam_upload_ticket_expired' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('vocabulary:'||ticket.student_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-reset:audio-catalog',0));
 PERFORM learning_reset_private.assert_writable(ticket.student_id);
 SELECT * INTO ticket FROM public.sitov_exam_upload_tickets WHERE path=NEW.name;
 IF ticket.student_id IS NULL OR (EXISTS(SELECT 1 FROM learning_reset_private.jobs WHERE auth_user_id=ticket.student_id AND completed_at>=ticket.created_at)
 AND NOT sitov_simulation_private.preserve_media(ticket.student_id,NEW.name))
 THEN RAISE EXCEPTION 'exam_upload_ticket_expired' USING ERRCODE='55000'; END IF;
 needs_ticket:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN needs_ticket:=OLD.metadata->>'size' IS NULL OR NEW.metadata->>'size' IS DISTINCT FROM OLD.metadata->>'size'; END IF;
 IF needs_ticket AND ticket.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'exam_upload_ticket_expired' USING ERRCODE='55000'; END IF;
 IF needs_ticket AND ticket.expected_bytes IS NOT NULL AND
 sitov_storage_private.object_bytes(NEW.metadata,20971520)>ticket.expected_bytes AND NEW.metadata->>'size' IS NOT NULL
 THEN RAISE EXCEPTION 'sitov_storage_file_too_large' USING ERRCODE='PT413'; END IF;
 RETURN NEW;
END $$;

-- Only server-side, authenticated and content-authorized actions receive the
-- service-role RPC. The daily counters survive worker restarts and file deletes.
CREATE OR REPLACE FUNCTION public.sitov_reserve_audio_generation(p_user_id uuid,p_characters integer)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 IF p_characters NOT BETWEEN 1 AND 3000 OR p_characters IS NULL OR
 NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND role IN('student','teacher','admin'))
 THEN RETURN false; END IF;
 PERFORM sitov_storage_private.charge_daily('synthesis:all',1,p_characters,500,1000000);
 PERFORM sitov_storage_private.charge_daily('synthesis:user:'||p_user_id::text,1,p_characters,100,100000);
 RETURN true;
EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN false;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA sitov_storage_private FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA sitov_storage_private TO service_role;
REVOKE ALL ON FUNCTION public.sitov_reserve_audio_generation(uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sitov_reserve_audio_generation(uuid,integer) TO service_role;
REVOKE ALL ON FUNCTION sitov_exam_private.guard_storage_upload() FROM PUBLIC,anon,authenticated;
NOTIFY pgrst,'reload schema';

-- END SITOV STORAGE SECURITY LIMITS

-- BEGIN SITOV STAFF MFA
-- Stage enrollment first. Existing staff keep access until they enable TOTP or
-- the operator sets sitov_mfa_required=true after verifying enrollment/recovery.
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS sitov_mfa_required boolean NOT NULL DEFAULT false;
CREATE SCHEMA IF NOT EXISTS sitov_security_private;
REVOKE ALL ON SCHEMA sitov_security_private FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA sitov_security_private TO authenticated,service_role;

CREATE OR REPLACE FUNCTION sitov_security_private.sitov_staff_mfa_required() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid())
  AND role IN('teacher','admin') AND sitov_mfa_required)
$$;
CREATE OR REPLACE FUNCTION sitov_security_private.sitov_staff_mfa_satisfied() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT NOT sitov_security_private.sitov_staff_mfa_required() OR
  (COALESCE((SELECT auth.jwt())->>'aal','')='aal2' AND EXISTS(
   SELECT 1 FROM auth.mfa_factors WHERE user_id=(SELECT auth.uid()) AND status='verified' AND factor_type='totp'))
$$;
REVOKE ALL ON FUNCTION sitov_security_private.sitov_staff_mfa_required(),sitov_security_private.sitov_staff_mfa_satisfied() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION sitov_security_private.sitov_staff_mfa_required(),sitov_security_private.sitov_staff_mfa_satisfied() TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.sitov_staff_mfa_status() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('required',sitov_security_private.sitov_staff_mfa_required(),
  'satisfied',sitov_security_private.sitov_staff_mfa_satisfied()) WHERE auth.uid() IS NOT NULL
$$;
REVOKE ALL ON FUNCTION public.sitov_staff_mfa_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sitov_staff_mfa_status() TO authenticated,service_role;

-- Learners/staff cannot disable their own mandatory flag through profile PATCH.
CREATE OR REPLACE FUNCTION sitov_security_private.sitov_protect_mfa_flag() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.role IN('teacher','admin') THEN NEW.sitov_mfa_required:=true; END IF;
  RETURN NEW;
 END IF;
 -- New staff and promotions inherit mandatory MFA after the enrollment path
 -- exists, without changing the staged flags of existing staff on deployment.
 IF NEW.role IN('teacher','admin') AND COALESCE(OLD.role::text,'') NOT IN('teacher','admin') THEN
  NEW.sitov_mfa_required:=true;
  RETURN NEW;
 END IF;
 IF NEW.sitov_mfa_required IS DISTINCT FROM OLD.sitov_mfa_required
  AND auth.uid() IS NOT NULL AND COALESCE((SELECT auth.jwt())->>'role','')<>'service_role'
  AND COALESCE(current_setting('sitov.staff_mfa_enable',true),'')<>'verified' THEN
  RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_security_private.sitov_protect_mfa_flag() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sitov_protect_mfa_flag ON public.profiles;
CREATE TRIGGER sitov_protect_mfa_flag BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION sitov_security_private.sitov_protect_mfa_flag();

CREATE OR REPLACE FUNCTION public.sitov_enable_staff_mfa() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous text:=current_setting('sitov.staff_mfa_enable',true);
BEGIN
 IF auth.uid() IS NULL OR COALESCE((SELECT auth.jwt())->>'aal','')<>'aal2'
  OR NOT EXISTS(SELECT 1 FROM auth.mfa_factors WHERE user_id=(SELECT auth.uid()) AND status='verified' AND factor_type='totp')
  OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid()) AND role IN('teacher','admin')) THEN
  RAISE EXCEPTION 'staff_mfa_required' USING ERRCODE='42501';
 END IF;
 PERFORM set_config('sitov.staff_mfa_enable','verified',true);
 UPDATE public.profiles SET sitov_mfa_required=true WHERE id=(SELECT auth.uid());
 PERFORM set_config('sitov.staff_mfa_enable',COALESCE(previous,''),true);
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.sitov_enable_staff_mfa() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sitov_enable_staff_mfa() TO authenticated;

-- This hook also covers SECURITY DEFINER RPCs which would bypass table RLS.
-- Only the current profile's read and the two MFA RPCs remain usable at aal1.
CREATE OR REPLACE FUNCTION sitov_security_private.sitov_pre_request() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE route text:=COALESCE(current_setting('request.path',true),'');
 method text:=COALESCE(current_setting('request.method',true),'');
BEGIN
 IF NOT sitov_security_private.sitov_staff_mfa_satisfied() THEN
  IF route IN('/rpc/sitov_staff_mfa_status','/rpc/sitov_enable_staff_mfa')
   OR (route='/profiles' AND method IN('GET','HEAD')) THEN RETURN; END IF;
  RAISE EXCEPTION 'staff_mfa_required' USING ERRCODE='42501';
 END IF;
END $$;
REVOKE ALL ON FUNCTION sitov_security_private.sitov_pre_request() FROM PUBLIC;
GRANT USAGE ON SCHEMA sitov_security_private TO anon;
GRANT EXECUTE ON FUNCTION sitov_security_private.sitov_pre_request() TO anon,authenticated,service_role;

-- Restrictive policies are ANDed with existing ownership/access rules. Storage
-- uses its own database connection, so it needs the same guard separately.
DO $$ DECLARE tab record;
BEGIN
 FOR tab IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind IN('r','p') AND c.relrowsecurity AND
   (n.nspname='public' OR (n.nspname='storage' AND c.relname IN('objects','buckets')))
 LOOP
  IF tab.nspname='public' AND tab.relname='profiles' THEN CONTINUE; END IF;
  EXECUTE format('DROP POLICY IF EXISTS sitov_staff_mfa ON %I.%I',tab.nspname,tab.relname);
  EXECUTE format('CREATE POLICY sitov_staff_mfa ON %I.%I AS RESTRICTIVE FOR ALL TO authenticated USING((SELECT sitov_security_private.sitov_staff_mfa_satisfied())) WITH CHECK((SELECT sitov_security_private.sitov_staff_mfa_satisfied()))',tab.nspname,tab.relname);
 END LOOP;
END $$;
DROP POLICY IF EXISTS sitov_staff_mfa_read ON public.profiles;
CREATE POLICY sitov_staff_mfa_read ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated
 USING((SELECT sitov_security_private.sitov_staff_mfa_satisfied()) OR id=(SELECT auth.uid()));
DO $$ DECLARE op text;
BEGIN
 FOREACH op IN ARRAY ARRAY['insert','update','delete'] LOOP
  EXECUTE format('DROP POLICY IF EXISTS sitov_staff_mfa_%s ON public.profiles',op);
  EXECUTE format('CREATE POLICY sitov_staff_mfa_%s ON public.profiles AS RESTRICTIVE FOR %s TO authenticated %s',op,upper(op),
   CASE WHEN op='insert' THEN 'WITH CHECK((SELECT sitov_security_private.sitov_staff_mfa_satisfied()))'
    WHEN op='delete' THEN 'USING((SELECT sitov_security_private.sitov_staff_mfa_satisfied()))'
    ELSE 'USING((SELECT sitov_security_private.sitov_staff_mfa_satisfied())) WITH CHECK((SELECT sitov_security_private.sitov_staff_mfa_satisfied()))' END);
 END LOOP;
END $$;

DO $$ DECLARE previous text;
BEGIN
 FOR previous IN SELECT substring(setting FROM length('pgrst.db_pre_request=')+1)
  FROM pg_db_role_setting s CROSS JOIN LATERAL unnest(s.setconfig) setting
  WHERE s.setrole=(SELECT oid FROM pg_roles WHERE rolname='authenticator')
   AND s.setdatabase IN(0,(SELECT oid FROM pg_database WHERE datname=current_database()))
   AND setting LIKE 'pgrst.db_pre_request=%'
 LOOP
  IF previous IS NOT NULL AND previous<>'' AND previous<>'sitov_security_private.sitov_pre_request' THEN
   RAISE EXCEPTION 'Existing PostgREST pre-request hook must be composed before enabling Sitov Academy MFA';
  END IF;
 END LOOP;
 ALTER ROLE authenticator SET pgrst.db_pre_request='sitov_security_private.sitov_pre_request';
 -- Database-specific settings outrank global role settings, including an
 -- explicit empty value. Set both so neither can silently disable this guard.
 EXECUTE format('ALTER ROLE authenticator IN DATABASE %I SET pgrst.db_pre_request=%L',current_database(),'sitov_security_private.sitov_pre_request');
END $$;
NOTIFY pgrst,'reload config';
NOTIFY pgrst,'reload schema';

-- END SITOV STAFF MFA

-- BEGIN SITOV EXPLICIT API DEFAULT PRIVILEGES
-- Preserve existing grants. Future application objects require explicit API grants
-- and RLS in their authoring migration; no automatic client access on creation.
-- PUBLIC's default function EXECUTE is global, so a schema-only REVOKE cannot
-- remove it. Revoke that default for both application DDL owners explicitly.
alter default privileges for role postgres in schema public
  revoke all privileges on tables from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all privileges on sequences from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all privileges on functions from anon, authenticated;
alter default privileges for role postgres
  revoke execute on functions from public;

alter default privileges for role supabase_admin in schema public
  revoke all privileges on tables from anon, authenticated;
alter default privileges for role supabase_admin in schema public
  revoke all privileges on sequences from anon, authenticated;
alter default privileges for role supabase_admin in schema public
  revoke all privileges on functions from anon, authenticated;
alter default privileges for role supabase_admin
  revoke execute on functions from public;

-- Leave vendor-owned auth/storage/realtime schemas and existing objects intact.
-- Include service_role explicitly for new server-only public objects.
alter default privileges for role supabase_admin in schema public
  grant all privileges on tables to service_role;
alter default privileges for role supabase_admin in schema public
  grant all privileges on sequences to service_role;
alter default privileges for role supabase_admin in schema public
  grant execute on functions to service_role;

-- END SITOV EXPLICIT API DEFAULT PRIVILEGES

-- BEGIN SITOV OPTIONAL COURSE RECORDING
-- Replace the two legacy unconditional recording promises without changing course identifiers or bookings.
UPDATE public.courses
SET description = replace(description,
 'inklusive Unterrichtsaufzeichnung für die eigene Wiederholung im Anschluss und intensivem 24/7 Telegram-Support',
 'mit intensivem 24/7 Telegram-Support')
 || ' Unterrichtsaufzeichnungen zur Wiederholung sind nur mit freiwilliger Einwilligung aller erfassten Personen möglich. Die Anmeldung ist auch ohne Aufnahmeeinwilligung möglich.'
WHERE slug IN ('deutsch-b1-online','deutsch-a1-1-online')
 AND strpos(description,'inklusive Unterrichtsaufzeichnung für die eigene Wiederholung im Anschluss und intensivem 24/7 Telegram-Support') > 0;
-- END SITOV OPTIONAL COURSE RECORDING

-- BEGIN SITOV TEACHER PASSWORD LOGIN
-- The operator chooses password-only teacher access. Admin protection remains.
CREATE OR REPLACE FUNCTION sitov_security_private.sitov_staff_mfa_required() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid())
  AND role='admin' AND sitov_mfa_required)
$$;
REVOKE ALL ON FUNCTION sitov_security_private.sitov_staff_mfa_required() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION sitov_security_private.sitov_staff_mfa_required() TO authenticated,service_role;

CREATE OR REPLACE FUNCTION sitov_security_private.sitov_protect_mfa_flag() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 -- Teacher profiles never regain mandatory MFA through enrollment, an old
 -- role promotion rule or an explicit true value in a profile write.
 IF NEW.role='teacher' THEN
  NEW.sitov_mfa_required:=false;
  RETURN NEW;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.role='admin' THEN NEW.sitov_mfa_required:=true; END IF;
  RETURN NEW;
 END IF;
 -- In particular, teacher -> admin must enable MFA despite the old staff role.
 IF NEW.role='admin' AND COALESCE(OLD.role::text,'')<>'admin' THEN
  NEW.sitov_mfa_required:=true;
  RETURN NEW;
 END IF;
 IF NEW.sitov_mfa_required IS DISTINCT FROM OLD.sitov_mfa_required
  AND auth.uid() IS NOT NULL AND COALESCE((SELECT auth.jwt())->>'role','')<>'service_role'
  AND COALESCE(current_setting('sitov.staff_mfa_enable',true),'')<>'verified' THEN
  RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sitov_security_private.sitov_protect_mfa_flag() FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.sitov_enable_staff_mfa() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous text:=current_setting('sitov.staff_mfa_enable',true);
BEGIN
 IF auth.uid() IS NULL OR COALESCE((SELECT auth.jwt())->>'aal','')<>'aal2'
  OR NOT EXISTS(SELECT 1 FROM auth.mfa_factors WHERE user_id=(SELECT auth.uid()) AND status='verified' AND factor_type='totp')
  OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid()) AND role='admin') THEN
  RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
 END IF;
 PERFORM set_config('sitov.staff_mfa_enable','verified',true);
 UPDATE public.profiles SET sitov_mfa_required=true WHERE id=(SELECT auth.uid());
 PERFORM set_config('sitov.staff_mfa_enable',COALESCE(previous,''),true);
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.sitov_enable_staff_mfa() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sitov_enable_staff_mfa() TO authenticated;

UPDATE public.profiles SET sitov_mfa_required=false WHERE role='teacher';
NOTIFY pgrst,'reload schema';
-- END SITOV TEACHER PASSWORD LOGIN

-- BEGIN SITOV ONLINE RECORDING REQUIREMENT
-- Require recording consent for new online group registrations/trials.
-- Existing bookings and their recorded choices are preserved. The deployment
-- runner owns the transaction; no consent is inferred or backfilled.
-- Normalize the frozen multilingual notice once. A version is never silently
-- overwritten; mismatched text aborts the whole runner-owned transaction.
CREATE TABLE IF NOT EXISTS business_private.sitov_recording_notices (
 version text PRIMARY KEY CHECK(length(version) BETWEEN 1 AND 100),
 payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND payload->>'version' IS NOT DISTINCT FROM version)
);
ALTER TABLE business_private.sitov_recording_notices ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON business_private.sitov_recording_notices FROM PUBLIC,anon,authenticated,service_role;
DO $sitov_notice_snapshot$
DECLARE frozen_notice jsonb:=$sitov_recording_notice${
  "version": "sitov-recording-2026-10-04-v1",
  "translations": {
    "de": {
      "registration": {
